    private async void OnLoaded(object sender, RoutedEventArgs e)
    {
        Loaded -= OnLoaded;
        await EditorWebView.EnsureCoreWebView2Async();

        EditorWebView.CoreWebView2.WebMessageReceived +=
            OnWebMessageReceived;

        var devUrl = Environment.GetEnvironmentVariable(
            "MAPSTUDIO_DEV_URL");

        if (Uri.TryCreate(
                devUrl,
                UriKind.Absolute,
                out var developmentUri))
        {
            EditorWebView.Source = developmentUri;
            return;
        }

        var uiDirectory = Path.Combine(
            AppContext.BaseDirectory,
            "ui");

        var indexPath = Path.Combine(
            uiDirectory,
            "index.html");

        if (!File.Exists(indexPath))
        {
            EditorWebView.NavigateToString(
                "<html><body style='font-family:Segoe UI;background:#101318;color:#fff;padding:32px'>" +
                "<h1>OMSI Map Studio</h1><p>UI build not found.</p>" +
                "<p>Run npm run build in src/MapStudio.UI or set MAPSTUDIO_DEV_URL.</p>" +
                "</body></html>");
            return;
        }

        EditorWebView.CoreWebView2
            .SetVirtualHostNameToFolderMapping(
                "app.mapstudio",
                uiDirectory,
                CoreWebView2HostResourceAccessKind.DenyCors);

        EditorWebView.Source = new Uri(
            "https://app.mapstudio/index.html");
    }

    private async void OnWebMessageReceived(
        object? sender,
        CoreWebView2WebMessageReceivedEventArgs e)
    {
        try
        {
            using var message =
                JsonDocument.Parse(
                    e.WebMessageAsJson);

            if (!message.RootElement.TryGetProperty(
                    "type",
                    out var typeElement))
            {
                return;
            }

            switch (typeElement.GetString())
            {
                case "selectOmsiRoot":
                    await SelectOmsiRootAsync();
                    break;

                case "selectMap":
                    await SelectMapAsync();
                    break;

                case "loadSceneryLibrary":
                    await LoadSceneryLibraryAsync();
                    break;

                case "loadSplineLibrary":
                    await LoadSplineLibraryAsync();
                    break;

                case "insertSplineFromLibrary":
                    if (
                        TryReadSplineLibraryInsertionRequest(
                            message.RootElement,
                            out var splineLibraryInsertionRequest))
                    {
                        await InsertSplineFromLibraryAsync(
                            splineLibraryInsertionRequest);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "insertObject":
                    if (
                        TryReadString(
                            message.RootElement,
                            "directoryName",
                            out var insertDirectoryName) &&
                        TryReadString(
                            message.RootElement,
                            "sceneryObjectPath",
                            out var insertSceneryObjectPath) &&
                        TryReadInt32(
                            message.RootElement,
                            "tileX",
                            out var insertTileX) &&
                        TryReadInt32(
                            message.RootElement,
                            "tileY",
                            out var insertTileY) &&
                        TryReadDouble(
                            message.RootElement,
                            "x",
                            out var insertX) &&
                        TryReadDouble(
                            message.RootElement,
                            "y",
                            out var insertY) &&
                        TryReadDouble(
                            message.RootElement,
                            "z",
                            out var insertZ) &&
                        TryReadDouble(
                            message.RootElement,
                            "rotation",
                            out var insertRotation) &&
                        TryReadDouble(
                            message.RootElement,
                            "pitch",
                            out var insertPitch) &&
                        TryReadDouble(
                            message.RootElement,
                            "bank",
                            out var insertBank))
                    {
                        await InsertObjectAsync(
                            insertDirectoryName,
                            insertSceneryObjectPath,
                            insertTileX,
                            insertTileY,
                            insertX,
                            insertY,
                            insertZ,
                            insertRotation,
                            insertPitch,
                            insertBank);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "deleteObject":
                    if (
                        TryReadString(
                            message.RootElement,
                            "directoryName",
                            out var deleteDirectoryName) &&
                        TryReadInt32(
                            message.RootElement,
                            "tileX",
                            out var deleteTileX) &&
                        TryReadInt32(
                            message.RootElement,
                            "tileY",
                            out var deleteTileY) &&
                        TryReadInt32(
                            message.RootElement,
                            "sourceSectionOrdinal",
                            out var deleteSourceSectionOrdinal) &&
                        TryReadString(
                            message.RootElement,
                            "sceneryObjectPath",
                            out var deleteSceneryObjectPath) &&
                        TryReadInt32(
                            message.RootElement,
                            "objectId",
                            out var deleteObjectId))
                    {
                        await DeleteObjectAsync(
                            deleteDirectoryName,
                            deleteTileX,
                            deleteTileY,
                            deleteSourceSectionOrdinal,
                            deleteSceneryObjectPath,
                            deleteObjectId);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "saveObjectTransforms":
                    if (
                        TryReadString(
                            message.RootElement,
                            "directoryName",
                            out var saveDirectoryName) &&
                        TryReadObjectTransformRequests(
                            message.RootElement,
                            out var transformRequests))
                    {
                        await SaveObjectTransformsAsync(
                            saveDirectoryName,
                            transformRequests);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "deleteSpline":
                    if (
                        TryReadString(
                            message.RootElement,
                            "directoryName",
                            out var deleteSplineDirectoryName) &&
                        TryReadInt32(
                            message.RootElement,
                            "tileX",
                            out var deleteSplineTileX) &&
                        TryReadInt32(
                            message.RootElement,
                            "tileY",
                            out var deleteSplineTileY) &&
                        TryReadInt32(
                            message.RootElement,
                            "sourceSectionOrdinal",
                            out var deleteSplineSourceSectionOrdinal) &&
                        TryReadString(
                            message.RootElement,
                            "splinePath",
                            out var deleteSplinePath) &&
                        TryReadInt32(
                            message.RootElement,
                            "splineId",
                            out var deleteSplineId) &&
                        TryReadInt32(
                            message.RootElement,
                            "previousSplineId",
                            out var deleteSplinePreviousId) &&
                        TryReadInt32(
                            message.RootElement,
                            "nextSplineId",
                            out var deleteSplineNextId) &&
                        TryReadBoolean(
                            message.RootElement,
                            "isHeightSpline",
                            out var deleteSplineIsHeight))
                    {
                        await DeleteSplineAsync(
                            deleteSplineDirectoryName,
                            deleteSplineTileX,
                            deleteSplineTileY,
                            deleteSplineSourceSectionOrdinal,
                            deleteSplinePath,
                            deleteSplineId,
                            deleteSplinePreviousId,
                            deleteSplineNextId,
                            deleteSplineIsHeight);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "insertSpline":
                    if (
                        TryReadSplineInsertionRequest(
                            message.RootElement,
                            out var splineInsertionRequest))
                    {
                        await InsertSplineAsync(
                            splineInsertionRequest);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "updateSplineLinks":
                    if (
                        TryReadSplineLinkRequest(
                            message.RootElement,
                            out var splineLinkRequest))
                    {
                        await UpdateSplineLinksAsync(
                            splineLinkRequest);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "saveSplineTransforms":
                    if (
                        TryReadString(
                            message.RootElement,
                            "directoryName",
                            out var splineSaveDirectoryName) &&
                        TryReadSplineTransformRequests(
                            message.RootElement,
                            out var splineTransformRequests))
                    {
                        await SaveSplineTransformsAsync(
                            splineSaveDirectoryName,
                            splineTransformRequests);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "loadMapFull":
                    if (TryReadString(
                            message.RootElement,
                            "directoryName",
                            out var fullMapDirectoryName))
                    {
                        await LoadMapFullAsync(
                            fullMapDirectoryName);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "loadMapRegion":
                    if (TryReadString(
                            message.RootElement,
                            "directoryName",
                            out var directoryName) &&
                        TryReadInt32(
                            message.RootElement,
                            "centerX",
                            out var centerX) &&
                        TryReadInt32(
                            message.RootElement,
                            "centerY",
                            out var centerY) &&
                        TryReadInt32(
                            message.RootElement,
                            "radius",
                            out var radius))
                    {
                        await LoadMapRegionAsync(
                            directoryName,
                            centerX,
                            centerY,
                            radius);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "loadSceneryTextureAsset":
                    if (
                        TryReadString(
                            message.RootElement,
                            "requestKey",
                            out var sceneryTextureRequestKey) &&
                        TryReadString(
                            message.RootElement,
                            "sceneryObjectPath",
                            out var textureSceneryObjectPath) &&
                        TryReadString(
                            message.RootElement,
                            "declaredMeshPath",
                            out var textureDeclaredMeshPath) &&
                        TryReadString(
                            message.RootElement,
                            "textureName",
                            out var sceneryTextureName))
                    {
                        await LoadSceneryTextureAssetAsync(
                            sceneryTextureRequestKey,
                            textureSceneryObjectPath,
                            textureDeclaredMeshPath,
                            sceneryTextureName);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "loadSplineTextureAsset":
                    if (
                        TryReadString(
                            message.RootElement,
                            "requestKey",
                            out var splineTextureRequestKey) &&
                        TryReadString(
                            message.RootElement,
                            "splinePath",
                            out var textureSplinePath) &&
                        TryReadString(
                            message.RootElement,
                            "textureName",
                            out var splineTextureName))
                    {
                        await LoadSplineTextureAssetAsync(
                            splineTextureRequestKey,
                            textureSplinePath,
                            splineTextureName);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "loadSplineProfile":
                    if (TryReadString(
                            message.RootElement,
                            "splinePath",
                            out var splinePath))
                    {
                        await LoadSplineProfileAsync(
                            splinePath);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "loadSceneryObjectMetadata":
                    if (TryReadString(
                            message.RootElement,
                            "sceneryObjectPath",
                            out var sceneryObjectPath))
                    {
                        await LoadSceneryObjectMetadataAsync(
                            sceneryObjectPath);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;

                case "loadSceneryObjectGeometry":
                    if (TryReadString(
                            message.RootElement,
                            "sceneryObjectPath",
                            out var geometryObjectPath))
                    {
                        await LoadSceneryObjectGeometryAsync(
                            geometryObjectPath);
                    }
                    else
                    {
                        PostInvalidMessage();
                    }
                    break;
            }
        }
        catch (JsonException)
        {
            PostInvalidMessage();
        }
        catch (Exception exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unexpectedHostError",
                detail = exception.Message
            });
        }
    }

    private Task SelectOmsiRootAsync()
    {
        var dialog = new OpenFolderDialog
        {
            Title = "Selecione a pasta raiz do OMSI 2",
            Multiselect = false
        };

        if (dialog.ShowDialog(this) != true)
        {
            PostMessage(new
            {
                type = "selectionCancelled",
                target = "omsi"
            });

            return Task.CompletedTask;
        }

        var rootPath =
            Path.GetFullPath(
                dialog.FolderName);

        var mapsPath =
            Path.Combine(
                rootPath,
                "maps");

        if (!Directory.Exists(mapsPath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidOmsiRoot",
                detail = rootPath
            });

            return Task.CompletedTask;
        }

        _omsiRootPath = rootPath;

        _knownMaps =
            new Dictionary<string, OmsiMapDescriptor>(
                StringComparer.OrdinalIgnoreCase);

        _knownSceneryObjectPaths.Clear();
        _knownSplinePaths.Clear();
        _tileContentCache.Clear();
        _splineDefinitionCache.Clear();
        _sceneryLibraryCache = null;
        _splineLibraryCache = null;

        PostMessage(new
        {
            type = "omsiRootSelected",
            rootPath
        });

        return Task.CompletedTask;
    }

    private async Task SelectMapAsync()
    {
        if (_omsiRootPath is null)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "omsiRootRequired"
            });

            return;
        }

        var mapsRoot =
            Path.GetFullPath(
                Path.Combine(
                    _omsiRootPath,
                    "maps"))
            .TrimEnd(
                Path.DirectorySeparatorChar,
                Path.AltDirectorySeparatorChar);

        var dialog = new OpenFolderDialog
        {
            Title = "Selecione a pasta do mapa dentro de OMSI 2\\maps",
            Multiselect = false,
            InitialDirectory = mapsRoot
        };

        if (dialog.ShowDialog(this) != true)
        {
            PostMessage(new
            {
                type = "selectionCancelled",
                target = "map"
            });

            return;
        }

        var selectedDirectory =
            Path.GetFullPath(
                dialog.FolderName)
            .TrimEnd(
                Path.DirectorySeparatorChar,
                Path.AltDirectorySeparatorChar);

        var requiredPrefix =
            mapsRoot +
            Path.DirectorySeparatorChar;

        if (!selectedDirectory.StartsWith(
                requiredPrefix,
                StringComparison.OrdinalIgnoreCase))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "mapOutsideOmsiMaps",
                detail = selectedDirectory
            });

            return;
        }

        var globalConfigPath =
            Path.Combine(
                selectedDirectory,
                "global.cfg");

        if (!File.Exists(globalConfigPath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidMapFolder",
                detail = selectedDirectory
            });

            return;
        }

        try
        {
            var map =
                await OmsiMapCatalog.OpenMapAsync(
                    selectedDirectory);

            _knownSceneryObjectPaths.Clear();
            _tileContentCache.Clear();

            _knownMaps =
                new Dictionary<string, OmsiMapDescriptor>(
                    StringComparer.OrdinalIgnoreCase)
                {
                    [map.DirectoryName] = map
                };

            var initialTile =
                OmsiTileRegionSelector
                    .FindInitialTile(
                        map.Tiles);

            PostMessage(new
            {
                type = "mapOpened",
                initialTile = initialTile is null
                    ? null
                    : new
                    {
                        x = initialTile.X,
                        y = initialTile.Y
                    },
                map = new
                {
                    map.DirectoryName,
                    map.DisplayName,
                    map.DirectoryPath,
                    map.GlobalConfigPath,
                    map.UsesWorldCoordinates,
                    tiles = map.Tiles.Select(
                        tile => new
                        {
                            tile.X,
                            tile.Y,
                            tile.RelativeMapPath,
                            detailsLoaded = false,
                            fileExists = false,
                            objectCount = 0,
                            splineCount = 0,
                            splineAttachmentCount = 0,
                            terrainMarkerPresent =
                                false,
                            terrainFileExists =
                                false,
                            terrainFileSize = 0
                        })
                }
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = selectedDirectory
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "ioError",
                detail = exception.Message
            });
        }
        catch (Exception exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "mapOpenError",
                detail = exception.Message
            });
        }
    }

    private async Task LoadSceneryLibraryAsync()
    {
        if (_omsiRootPath is null)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "omsiRootRequired"
            });

            return;
        }

        var omsiRoot =
            _omsiRootPath;

        try
        {
            if (_sceneryLibraryCache is null)
            {
                var entries =
                    await Task.Run(
                        () =>
                            ScanSceneryLibrary(
                                omsiRoot));

                if (!string.Equals(
                        _omsiRootPath,
                        omsiRoot,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                _sceneryLibraryCache =
                    entries;
            }

            PostMessage(new
            {
                type =
                    "sceneryLibraryLoaded",
                entries =
                    _sceneryLibraryCache
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = "Sceneryobjects"
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "ioError",
                detail = exception.Message
            });
        }
    }

    private IReadOnlyList<SceneryLibraryEntry>
        ScanSceneryLibrary(
            string omsiRoot)
    {
        var root =
            Path.Combine(
                omsiRoot,
                "Sceneryobjects");

        if (!Directory.Exists(root))
        {
            return
                Array.Empty<SceneryLibraryEntry>();
        }

        var options =
            new EnumerationOptions
            {
                RecurseSubdirectories = true,
                IgnoreInaccessible = true,
                MatchCasing =
                    MatchCasing.CaseInsensitive,
                AttributesToSkip =
                    FileAttributes.ReparsePoint
            };

        var entries =
            new List<SceneryLibraryEntry>();

        foreach (var filePath in
            Directory.EnumerateFiles(
                root,
                "*.sco",
                options))
        {
            if (entries.Count >= 50000)
            {
                break;
            }

            var relative =
                Path.GetRelativePath(
                    root,
                    filePath)
                .Replace(
                    Path.DirectorySeparatorChar,
                    '\\');

            var declaredPath =
                "Sceneryobjects\\" +
                relative;

            entries.Add(
                new SceneryLibraryEntry(
                    declaredPath,
                    Path.GetFileName(
                        filePath)));

            _knownSceneryObjectPaths
                .TryAdd(
                    declaredPath,
                    0);
        }

        return entries
            .OrderBy(
                entry =>
                    entry.SceneryObjectPath,
                StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private async Task LoadSplineLibraryAsync()
    {
        if (_omsiRootPath is null)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "omsiRootRequired"
            });

            return;
        }

        var omsiRoot =
            _omsiRootPath;

        try
        {
            if (_splineLibraryCache is null)
            {
                var entries =
                    await Task.Run(
                        () =>
                            ScanSplineLibrary(
                                omsiRoot));

                if (!string.Equals(
                        _omsiRootPath,
                        omsiRoot,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                _splineLibraryCache =
                    entries;
            }

            PostMessage(new
            {
                type =
                    "splineLibraryLoaded",
                entries =
                    _splineLibraryCache
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = "Splines"
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "ioError",
                detail = exception.Message
            });
        }
    }

    private IReadOnlyList<SplineLibraryEntry>
        ScanSplineLibrary(
            string omsiRoot)
    {
        var root =
            Path.Combine(
                omsiRoot,
                "Splines");

        if (!Directory.Exists(root))
        {
            return
                Array.Empty<SplineLibraryEntry>();
        }

        var options =
            new EnumerationOptions
            {
                RecurseSubdirectories = true,
                IgnoreInaccessible = true,
                MatchCasing =
                    MatchCasing.CaseInsensitive,
                AttributesToSkip =
                    FileAttributes.ReparsePoint
            };

        var entries =
            new List<SplineLibraryEntry>();

        foreach (var filePath in
            Directory.EnumerateFiles(
                root,
                "*.sli",
                options))
        {
            if (entries.Count >= 50000)
            {
                break;
            }

            var relative =
                Path.GetRelativePath(
                    root,
                    filePath)
                .Replace(
                    Path.DirectorySeparatorChar,
                    '\\');

            var declaredPath =
                "Splines\\" +
                relative;

            entries.Add(
                new SplineLibraryEntry(
                    declaredPath,
                    Path.GetFileName(
                        filePath)));

            _knownSplinePaths.TryAdd(
                declaredPath,
                0);
        }

        return entries
            .OrderBy(
                entry =>
                    entry.SplinePath,
                StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private async Task InsertSplineFromLibraryAsync(
        SplineLibraryInsertionRequest request)
    {
        if (
            !_knownMaps.TryGetValue(
                request.DirectoryName,
                out var map))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownMap"
            });

            return;
        }

        if (
            _omsiRootPath is null ||
            !_knownSplinePaths
                .ContainsKey(
                    request.SplinePath) ||
            !OmsiSplinePathResolver
                .TryResolve(
                    _omsiRootPath,
                    request.SplinePath,
                    out var splineFullPath) ||
            !File.Exists(splineFullPath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidSplinePath"
            });

            return;
        }

        if (map.UsesWorldCoordinates)
        {
            PostMessage(new
            {
                type = "hostError",
                code =
                    "splineInsertionWorldCoordinatesUnsupported"
            });

            return;
        }

        var targetTile =
            map.Tiles.FirstOrDefault(
                tile =>
                    tile.X ==
                        request.TargetTileX &&
                    tile.Y ==
                        request.TargetTileY);

        if (targetTile is null)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownTile"
            });

            return;
        }

        if (!OmsiMapPathResolver
            .TryResolveTilePath(
                map.DirectoryPath,
                targetTile.RelativeMapPath,
                out var targetTilePath) ||
            !File.Exists(targetTilePath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidTilePath"
            });

            return;
        }

        try
        {
            var snapshot =
                await ReadMapInsertionSnapshotAsync(
                    map);

            var template =
                OmsiSplinePlacementTemplateAnalyzer
                    .FindNeutralTemplate(
                        snapshot.Contents,
                        request.IsHeightSpline);

            if (template is null)
            {
                PostMessage(new
                {
                    type = "hostError",
                    code =
                        "splineInsertTemplateUnavailable",
                    detail =
                        request.SplinePath
                });

                return;
            }

            if (
                snapshot.MaxUsedId >=
                    int.MaxValue)
            {
                throw new InvalidDataException(
                    "splineIdExhausted");
            }

            var document =
                await OmsiConfigParser
                    .ParseFileAsync(
                        targetTilePath);

            var nextId =
                checked(
                    snapshot.MaxUsedId + 1);

            var result =
                OmsiTileSplineInserter
                    .Append(
                        document,
                        new OmsiNewPlacedSpline(
                            template.HeaderValue,
                            request.SplinePath,
                            nextId,
                            -1,
                            -1,
                            request.X,
                            request.Z,
                            request.Y,
                            request.Rotation,
                            request.Length,
                            request.Radius,
                            request.GradientStart,
                            request.GradientEnd,
                            request.IsHeightSpline,
                            template.ExtraValues));

            var timestamp =
                DateTimeOffset.UtcNow
                    .ToString(
                        "yyyyMMdd-HHmmssfff'Z'",
                        CultureInfo.InvariantCulture);

            var relativePath =
                Path.GetRelativePath(
                    map.DirectoryPath,
                    targetTilePath);

            if (
                relativePath.StartsWith(
                    "..",
                    StringComparison.Ordinal) ||
                Path.IsPathRooted(
                    relativePath))
            {
                throw new InvalidDataException(
                    "invalidTilePath");
            }

            var backupRoot =
                Path.Combine(
                    map.DirectoryPath,
                    ".mapstudio-backups",
                    timestamp);

            await SafeFileTransaction
                .WriteAllAsync(
                    [
                        new PendingFileWrite(
                            targetTilePath,
                            Path.Combine(
                                backupRoot,
                                relativePath),
                            result.Bytes)
                    ]);

            _tileContentCache
                .TryRemove(
                    targetTilePath,
                    out _);

            PostMessage(new
            {
                type = "splineInserted",
                map.DirectoryName,
                backupDirectory =
                    backupRoot,
                placedSpline = new
                {
                    tileX =
                        request.TargetTileX,
                    tileY =
                        request.TargetTileY,
                    headerValue =
                        template.HeaderValue,
                    splinePath =
                        request.SplinePath,
                    splineId = nextId,
                    sourceSectionOrdinal =
                        result.SourceSectionOrdinal,
                    previousSplineId = -1,
                    nextSplineId = -1,
                    x = request.X,
                    z = request.Z,
                    y = request.Y,
                    rotation =
                        request.Rotation,
                    length =
                        request.Length,
                    radius =
                        request.Radius,
                    gradientStart =
                        request.GradientStart,
                    gradientEnd =
                        request.GradientEnd,
                    isHeightSpline =
                        request.IsHeightSpline
                }
            });
        }
        catch (InvalidDataException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code =
                    exception.Message ==
                        "splineIdExhausted"
                        ? "splineIdExhausted"
                        : "splineInsertError",
                detail = exception.Message
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = targetTilePath
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "splineInsertError",
                detail = exception.Message
            });
        }
    }

    private async Task InsertObjectAsync(
        string? directoryName,
        string? sceneryObjectPath,
        int tileX,
        int tileY,
        double x,
        double y,
        double z,
        double rotation,
        double pitch,
        double bank)
    {
        if (
            string.IsNullOrWhiteSpace(
                directoryName) ||
            !_knownMaps.TryGetValue(
                directoryName,
                out var map))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownMap"
            });

            return;
        }

        if (
            string.IsNullOrWhiteSpace(
                sceneryObjectPath) ||
            !_knownSceneryObjectPaths
                .ContainsKey(
                    sceneryObjectPath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownSceneryObject"
            });

            return;
        }

        if (
            _omsiRootPath is null ||
            !OmsiSceneryObjectPathResolver
                .TryResolve(
                    _omsiRootPath,
                    sceneryObjectPath,
                    out var sceneryFullPath) ||
            !File.Exists(
                sceneryFullPath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidSceneryObjectPath"
            });

            return;
        }

        if (
            map.UsesWorldCoordinates)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "objectInsertionWorldCoordinatesUnsupported"
            });

            return;
        }

        var targetTile =
            map.Tiles.FirstOrDefault(
                tile =>
                    tile.X == tileX &&
                    tile.Y == tileY);

        if (targetTile is null)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownTile"
            });

            return;
        }

        if (!OmsiMapPathResolver
            .TryResolveTilePath(
                map.DirectoryPath,
                targetTile.RelativeMapPath,
                out var targetTilePath) ||
            !File.Exists(
                targetTilePath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidTilePath"
            });

            return;
        }

        try
        {
            var snapshot =
                await ReadMapInsertionSnapshotAsync(
                    map);

            var contentAnalysis =
                OmsiObjectInsertionAnalyzer
                    .Analyze(
                        snapshot.Contents,
                        sceneryObjectPath);

            var analysis =
                new OmsiObjectInsertionAnalysis(
                    Math.Max(
                        contentAnalysis.MaxUsedId,
                        snapshot.MaxUsedId),
                    contentAnalysis
                        .MatchingObjectTemplate);

            var template =
                analysis
                    .MatchingObjectTemplate;

            if (template is null)
            {
                PostMessage(new
                {
                    type = "hostError",
                    code =
                        "objectInsertTemplateUnavailable",
                    detail =
                        sceneryObjectPath
                });

                return;
            }

            var nextId =
                analysis.GetNextId();

            var document =
                await OmsiConfigParser
                    .ParseFileAsync(
                        targetTilePath);

            var result =
                OmsiTileObjectInserter
                    .Append(
                        document,
                        new OmsiNewPlacedObject(
                            template.HeaderValue,
                            sceneryObjectPath,
                            nextId,
                            x,
                            y,
                            z,
                            rotation,
                            pitch,
                            bank,
                            template.ExtraValues));

            var timestamp =
                DateTimeOffset.UtcNow
                    .ToString(
                        "yyyyMMdd-HHmmssfff'Z'",
                        CultureInfo.InvariantCulture);

            var relativePath =
                Path.GetRelativePath(
                    map.DirectoryPath,
                    targetTilePath);

            if (
                relativePath.StartsWith(
                    "..",
                    StringComparison.Ordinal) ||
                Path.IsPathRooted(
                    relativePath))
            {
                throw new InvalidDataException(
                    "invalidTilePath");
            }

            var backupRoot =
                Path.Combine(
                    map.DirectoryPath,
                    ".mapstudio-backups",
                    timestamp);

            var backupPath =
                Path.Combine(
                    backupRoot,
                    relativePath);

            await SafeFileTransaction
                .WriteAllAsync(
                    [
                        new PendingFileWrite(
                            targetTilePath,
                            backupPath,
                            result.Bytes)
                    ]);

            _tileContentCache
                .TryRemove(
                    targetTilePath,
                    out _);

            PostMessage(new
            {
                type = "objectInserted",
                map.DirectoryName,
                backupDirectory =
                    backupRoot,
                placedObject = new
                {
                    tileX,
                    tileY,
                    headerValue =
                        template.HeaderValue,
                    sceneryObjectPath,
                    objectId = nextId,
                    sourceSectionOrdinal =
                        result.SourceSectionOrdinal,
                    x,
                    y,
                    z,
                    rotation,
                    pitch,
                    bank
                }
            });
        }
        catch (InvalidDataException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code =
                    exception.Message ==
                        "objectIdExhausted"
                        ? "objectIdExhausted"
                        : "objectInsertError",
                detail = exception.Message
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail =
                    targetTilePath
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "objectInsertError",
                detail = exception.Message
            });
        }
    }

