    private async Task<MapInsertionSnapshot>
        ReadMapInsertionSnapshotAsync(
            OmsiMapDescriptor map)
    {
        using var semaphore =
            new SemaphoreSlim(
                Math.Min(
                    MaxConcurrentTileReads,
                    Math.Max(
                        1,
                        Environment
                            .ProcessorCount)));

        var tasks =
            map.Tiles.Select(
                async tile =>
                {
                    await semaphore
                        .WaitAsync();

                    try
                    {
                        if (!OmsiMapPathResolver
                            .TryResolveTilePath(
                                map.DirectoryPath,
                                tile.RelativeMapPath,
                                out var path) ||
                            !File.Exists(path))
                        {
                            return (
                                Content:
                                    OmsiTileContent
                                        .Missing,
                                MaxUsedId: 0);
                        }

                        var document =
                            await OmsiConfigParser
                                .ParseFileAsync(
                                    path);

                        return (
                            Content:
                                OmsiTileReader
                                    .ReadContent(
                                        document),
                            MaxUsedId:
                                OmsiTileElementIdScanner
                                    .FindMaxUsedId(
                                        document));
                    }
                    finally
                    {
                        semaphore.Release();
                    }
                })
                .ToArray();

        var results =
            await Task.WhenAll(
                tasks);

        return new MapInsertionSnapshot(
            results
                .Select(result =>
                    result.Content)
                .ToArray(),
            results.Length == 0
                ? 0
                : results.Max(result =>
                    result.MaxUsedId));
    }

    private async Task SaveObjectTransformsAsync(
        string? directoryName,
        IReadOnlyList<ObjectTransformRequest> requests)
    {
        if (
            string.IsNullOrWhiteSpace(
                directoryName) ||
            !_knownMaps.TryGetValue(
                directoryName,
                out var map))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownMap"
            });

            return;
        }

        if (requests.Count == 0)
        {
            PostInvalidMessage();
            return;
        }

        try
        {
            var timestamp =
                DateTimeOffset.UtcNow
                    .ToString(
                        "yyyyMMdd-HHmmssfff'Z'",
                        CultureInfo.InvariantCulture);

            var backupRoot =
                Path.Combine(
                    map.DirectoryPath,
                    ".mapstudio-backups",
                    timestamp);

            var writes =
                new List<PendingFileWrite>();

            var editedTilePaths =
                new List<string>();

            var appliedEdits = 0;

            foreach (
                var group in requests
                    .GroupBy(request =>
                        (
                            request.TileX,
                            request.TileY)))
            {
                var tile =
                    map.Tiles.FirstOrDefault(
                        candidate =>
                            candidate.X ==
                                group.Key.TileX &&
                            candidate.Y ==
                                group.Key.TileY);

                if (tile is null)
                {
                    throw new InvalidDataException(
                        "unknownTile");
                }

                if (!OmsiMapPathResolver
                    .TryResolveTilePath(
                        map.DirectoryPath,
                        tile.RelativeMapPath,
                        out var tilePath))
                {
                    throw new InvalidDataException(
                        "invalidTilePath");
                }

                var document =
                    await OmsiConfigParser
                        .ParseFileAsync(
                            tilePath);

                var edits =
                    group.Select(
                        request =>
                            new OmsiObjectTransformEdit(
                                request.SourceSectionOrdinal,
                                request.SceneryObjectPath,
                                request.ObjectId,
                                request.X,
                                request.Y,
                                request.Z,
                                request.Rotation,
                                request.Pitch,
                                request.Bank))
                    .ToArray();

                var result =
                    OmsiTileObjectEditor
                        .ApplyTransforms(
                            document,
                            edits);

                var relativePath =
                    Path.GetRelativePath(
                        map.DirectoryPath,
                        tilePath);

                if (
                    relativePath.StartsWith(
                        "..",
                        StringComparison.Ordinal) ||
                    Path.IsPathRooted(
                        relativePath))
                {
                    throw new InvalidDataException(
                        "invalidTilePath");
                }

                var backupPath =
                    Path.Combine(
                        backupRoot,
                        relativePath);

                writes.Add(
                    new PendingFileWrite(
                        tilePath,
                        backupPath,
                        result.Bytes));

                editedTilePaths.Add(
                    tilePath);

                appliedEdits +=
                    result.AppliedEdits;
            }

            await SafeFileTransaction
                .WriteAllAsync(
                    writes);

            foreach (var tilePath in
                editedTilePaths)
            {
                _tileContentCache
                    .TryRemove(
                        tilePath,
                        out _);
            }

            PostMessage(new
            {
                type =
                    "objectTransformsSaved",
                map.DirectoryName,
                editsSaved =
                    appliedEdits,
                filesSaved =
                    writes.Count,
                backupDirectory =
                    backupRoot
            });
        }
        catch (InvalidDataException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "saveConflict",
                detail = exception.Message
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = map.DirectoryPath
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "saveError",
                detail = exception.Message
            });
        }
    }

    private async Task DeleteSplineAsync(
        string? directoryName,
        int tileX,
        int tileY,
        int sourceSectionOrdinal,
        string? splinePath,
        int splineId,
        int previousSplineId,
        int nextSplineId,
        bool isHeightSpline)
    {
        if (
            string.IsNullOrWhiteSpace(
                directoryName) ||
            !_knownMaps.TryGetValue(
                directoryName,
                out var map))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownMap"
            });

            return;
        }

        if (string.IsNullOrWhiteSpace(
                splinePath))
        {
            PostInvalidMessage();
            return;
        }

        try
        {
            var snapshot =
                await ReadMapInsertionSnapshotAsync(
                    map);

            var entries =
                new List<SplineMapEntry>();

            var count =
                Math.Min(
                    map.Tiles.Count,
                    snapshot.Contents.Count);

            for (
                var index = 0;
                index < count;
                index++)
            {
                var tile =
                    map.Tiles[index];

                foreach (var spline in
                    snapshot
                        .Contents[index]
                        .Splines)
                {
                    entries.Add(
                        new SplineMapEntry(
                            tile.X,
                            tile.Y,
                            tile.RelativeMapPath,
                            spline));
                }
            }

            if (
                entries
                    .GroupBy(entry =>
                        entry.Spline.SplineId)
                    .Any(group =>
                        group.Count() > 1))
            {
                throw new InvalidDataException(
                    "duplicateSplineId");
            }

            var byId =
                entries.ToDictionary(
                    entry =>
                        entry.Spline.SplineId);

            if (
                !byId.TryGetValue(
                    splineId,
                    out var source) ||
                source.TileX != tileX ||
                source.TileY != tileY ||
                source.Spline
                    .SourceSectionOrdinal !=
                    sourceSectionOrdinal ||
                source.Spline
                    .PreviousSplineId !=
                    previousSplineId ||
                source.Spline
                    .NextSplineId !=
                    nextSplineId ||
                source.Spline
                    .IsHeightSpline !=
                    isHeightSpline ||
                !string.Equals(
                    source.Spline.SplinePath,
                    splinePath,
                    StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidDataException(
                    "splineSourceChanged");
            }

            var states =
                byId.ToDictionary(
                    pair => pair.Key,
                    pair =>
                        new OmsiSplineLinkState(
                            pair.Key,
                            pair.Value
                                .Spline
                                .PreviousSplineId,
                            pair.Value
                                .Spline
                                .NextSplineId));

            var unlinkPlan =
                OmsiSplineLinkPlanner
                    .Plan(
                        states,
                        splineId,
                        previousSplineId,
                        nextSplineId,
                        -1,
                        -1);

            var affectedEntries =
                unlinkPlan.Keys
                    .Where(id =>
                        id != splineId)
                    .Select(id =>
                        byId[id])
                    .Append(source)
                    .GroupBy(entry =>
                        (
                            TileX: entry.TileX,
                            TileY: entry.TileY,
                            RelativeMapPath:
                                entry.RelativeMapPath))
                    .ToArray();

            var timestamp =
                DateTimeOffset.UtcNow
                    .ToString(
                        "yyyyMMdd-HHmmssfff'Z'",
                        CultureInfo.InvariantCulture);

            var backupRoot =
                Path.Combine(
                    map.DirectoryPath,
                    ".mapstudio-backups",
                    timestamp);

            var writes =
                new List<PendingFileWrite>();

            var editedTilePaths =
                new List<string>();

            var unlinkedSplines = 0;

            foreach (var group in
                affectedEntries)
            {
                if (!OmsiMapPathResolver
                    .TryResolveTilePath(
                        map.DirectoryPath,
                        group.Key
                            .RelativeMapPath,
                        out var tilePath) ||
                    !File.Exists(tilePath))
                {
                    throw new InvalidDataException(
                        "invalidTilePath");
                }

                var document =
                    await OmsiConfigParser
                        .ParseFileAsync(
                            tilePath);

                var linkEdits =
                    group
                        .Where(entry =>
                            entry.Spline.SplineId !=
                                splineId &&
                            unlinkPlan.ContainsKey(
                                entry.Spline
                                    .SplineId))
                        .Select(entry =>
                        {
                            var target =
                                unlinkPlan[
                                    entry.Spline
                                        .SplineId];

                            return new OmsiSplineLinkEdit(
                                entry.Spline
                                    .SourceSectionOrdinal,
                                entry.Spline
                                    .SplinePath,
                                entry.Spline
                                    .SplineId,
                                entry.Spline
                                    .PreviousSplineId,
                                entry.Spline
                                    .NextSplineId,
                                entry.Spline
                                    .IsHeightSpline,
                                target
                                    .PreviousSplineId,
                                target
                                    .NextSplineId);
                        })
                        .ToArray();

                if (linkEdits.Length > 0)
                {
                    var linkResult =
                        OmsiTileSplineLinkEditor
                            .ApplyLinks(
                                document,
                                linkEdits);

                    unlinkedSplines +=
                        linkResult.AppliedEdits;

                    document =
                        OmsiConfigParser
                            .ParseBytes(
                                linkResult.Bytes);
                }

                byte[] bytes;

                if (
                    group.Any(entry =>
                        entry.Spline.SplineId ==
                            splineId))
                {
                    var deleteResult =
                        OmsiTileSplineDeleter
                            .Remove(
                                document,
                                sourceSectionOrdinal,
                                splinePath,
                                splineId,
                                previousSplineId,
                                nextSplineId,
                                isHeightSpline);

                    bytes =
                        deleteResult.Bytes;
                }
                else
                {
                    bytes =
                        document.ToBytes();
                }

                var relativePath =
                    Path.GetRelativePath(
                        map.DirectoryPath,
                        tilePath);

                if (
                    relativePath.StartsWith(
                        "..",
                        StringComparison.Ordinal) ||
                    Path.IsPathRooted(
                        relativePath))
                {
                    throw new InvalidDataException(
                        "invalidTilePath");
                }

                writes.Add(
                    new PendingFileWrite(
                        tilePath,
                        Path.Combine(
                            backupRoot,
                            relativePath),
                        bytes));

                editedTilePaths.Add(
                    tilePath);
            }

            await SafeFileTransaction
                .WriteAllAsync(
                    writes);

            foreach (var tilePath in
                editedTilePaths)
            {
                _tileContentCache
                    .TryRemove(
                        tilePath,
                        out _);
            }

            PostMessage(new
            {
                type = "splineDeleted",
                map.DirectoryName,
                splineId,
                deletedSplines = 1,
                unlinkedSplines,
                filesSaved =
                    writes.Count,
                backupDirectory =
                    backupRoot
            });
        }
        catch (InvalidDataException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "splineDeleteConflict",
                detail = exception.Message
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = map.DirectoryPath
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "splineDeleteError",
                detail = exception.Message
            });
        }
    }

    private async Task InsertSplineAsync(
        SplineInsertionRequest request)
    {
        if (
            !_knownMaps.TryGetValue(
                request.DirectoryName,
                out var map))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownMap"
            });

            return;
        }

        if (
            _omsiRootPath is null ||
            !_knownSplinePaths
                .ContainsKey(
                    request.SplinePath) ||
            !OmsiSplinePathResolver
                .TryResolve(
                    _omsiRootPath,
                    request.SplinePath,
                    out var splineFullPath) ||
            !File.Exists(splineFullPath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidSplinePath"
            });

            return;
        }

        if (map.UsesWorldCoordinates)
        {
            PostMessage(new
            {
                type = "hostError",
                code =
                    "splineInsertionWorldCoordinatesUnsupported"
            });

            return;
        }

        var sourceTile =
            map.Tiles.FirstOrDefault(
                tile =>
                    tile.X ==
                        request.SourceTileX &&
                    tile.Y ==
                        request.SourceTileY);

        var targetTile =
            map.Tiles.FirstOrDefault(
                tile =>
                    tile.X ==
                        request.TargetTileX &&
                    tile.Y ==
                        request.TargetTileY);

        if (
            sourceTile is null ||
            targetTile is null)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownTile"
            });

            return;
        }

        if (
            !OmsiMapPathResolver
                .TryResolveTilePath(
                    map.DirectoryPath,
                    sourceTile.RelativeMapPath,
                    out var sourceTilePath) ||
            !File.Exists(sourceTilePath) ||
            !OmsiMapPathResolver
                .TryResolveTilePath(
                    map.DirectoryPath,
                    targetTile.RelativeMapPath,
                    out var targetTilePath) ||
            !File.Exists(targetTilePath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidTilePath"
            });

            return;
        }

        try
        {
            var snapshot =
                await ReadMapInsertionSnapshotAsync(
                    map);

            if (
                snapshot.MaxUsedId >=
                    int.MaxValue)
            {
                throw new InvalidDataException(
                    "splineIdExhausted");
            }

            var targetDocument =
                await OmsiConfigParser
                    .ParseFileAsync(
                        targetTilePath);

            var sourceDocument =
                string.Equals(
                    sourceTilePath,
                    targetTilePath,
                    StringComparison.OrdinalIgnoreCase)
                    ? targetDocument
                    : await OmsiConfigParser
                        .ParseFileAsync(
                            sourceTilePath);

            var sourceSpline =
                OmsiTileReader
                    .ReadSplines(
                        sourceDocument)
                    .FirstOrDefault(
                        candidate =>
                            candidate
                                .SourceSectionOrdinal ==
                            request
                                .SourceSectionOrdinal);

            if (
                sourceSpline is null ||
                sourceSpline.SplineId !=
                    request.SplineId ||
                sourceSpline.PreviousSplineId !=
                    request.PreviousSplineId ||
                sourceSpline.NextSplineId !=
                    request.NextSplineId ||
                sourceSpline.IsHeightSpline !=
                    request.IsHeightSpline ||
                !string.Equals(
                    sourceSpline.SplinePath,
                    request.SplinePath,
                    StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidDataException(
                    "splineSourceChanged");
            }

            var nextId =
                checked(
                    snapshot.MaxUsedId + 1);

            var result =
                OmsiTileSplineInserter
                    .Append(
                        targetDocument,
                        new OmsiNewPlacedSpline(
                            sourceSpline.HeaderValue,
                            sourceSpline.SplinePath,
                            nextId,
                            -1,
                            -1,
                            request.X,
                            request.Z,
                            request.Y,
                            request.Rotation,
                            request.Length,
                            request.Radius,
                            request.GradientStart,
                            request.GradientEnd,
                            sourceSpline.IsHeightSpline,
                            sourceSpline.ExtraValues));

            var timestamp =
                DateTimeOffset.UtcNow
                    .ToString(
                        "yyyyMMdd-HHmmssfff'Z'",
                        CultureInfo.InvariantCulture);

            var relativePath =
                Path.GetRelativePath(
                    map.DirectoryPath,
                    targetTilePath);

            if (
                relativePath.StartsWith(
                    "..",
                    StringComparison.Ordinal) ||
                Path.IsPathRooted(
                    relativePath))
            {
                throw new InvalidDataException(
                    "invalidTilePath");
            }

            var backupRoot =
                Path.Combine(
                    map.DirectoryPath,
                    ".mapstudio-backups",
                    timestamp);

            var backupPath =
                Path.Combine(
                    backupRoot,
                    relativePath);

            await SafeFileTransaction
                .WriteAllAsync(
                    [
                        new PendingFileWrite(
                            targetTilePath,
                            backupPath,
                            result.Bytes)
                    ]);

            _tileContentCache
                .TryRemove(
                    targetTilePath,
                    out _);

            PostMessage(new
            {
                type = "splineInserted",
                map.DirectoryName,
                backupDirectory =
                    backupRoot,
                placedSpline = new
                {
                    tileX =
                        request.TargetTileX,
                    tileY =
                        request.TargetTileY,
                    headerValue =
                        sourceSpline.HeaderValue,
                    splinePath =
                        sourceSpline.SplinePath,
                    splineId = nextId,
                    sourceSectionOrdinal =
                        result.SourceSectionOrdinal,
                    previousSplineId = -1,
                    nextSplineId = -1,
                    x = request.X,
                    z = request.Z,
                    y = request.Y,
                    rotation =
                        request.Rotation,
                    length =
                        request.Length,
                    radius =
                        request.Radius,
                    gradientStart =
                        request.GradientStart,
                    gradientEnd =
                        request.GradientEnd,
                    isHeightSpline =
                        sourceSpline.IsHeightSpline
                }
            });
        }
        catch (InvalidDataException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code =
                    exception.Message ==
                        "splineIdExhausted"
                        ? "splineIdExhausted"
                        : exception.Message ==
                            "splineSourceChanged"
                            ? "splineInsertConflict"
                            : "splineInsertError",
                detail = exception.Message
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = targetTilePath
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "splineInsertError",
                detail = exception.Message
            });
        }
    }

    private async Task UpdateSplineLinksAsync(
        SplineLinkRequest request)
    {
        if (
            !_knownMaps.TryGetValue(
                request.DirectoryName,
                out var map))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownMap"
            });

            return;
        }

        try
        {
            var snapshot =
                await ReadMapInsertionSnapshotAsync(
                    map);

            var entries =
                new List<SplineMapEntry>();

            var count =
                Math.Min(
                    map.Tiles.Count,
                    snapshot.Contents.Count);

            for (
                var index = 0;
                index < count;
                index++)
            {
                var tile =
                    map.Tiles[index];

                foreach (var spline in
                    snapshot
                        .Contents[index]
                        .Splines)
                {
                    entries.Add(
                        new SplineMapEntry(
                            tile.X,
                            tile.Y,
                            tile.RelativeMapPath,
                            spline));
                }
            }

            if (
                entries
                    .GroupBy(entry =>
                        entry.Spline.SplineId)
                    .Any(group =>
                        group.Count() > 1))
            {
                throw new InvalidDataException(
                    "duplicateSplineId");
            }

            var byId =
                entries.ToDictionary(
                    entry =>
                        entry.Spline.SplineId);

            if (
                !byId.TryGetValue(
                    request.SplineId,
                    out var source) ||
                source.TileX !=
                    request.TileX ||
                source.TileY !=
                    request.TileY ||
                source.Spline
                    .SourceSectionOrdinal !=
                    request
                        .SourceSectionOrdinal ||
                source.Spline
                    .PreviousSplineId !=
                    request
                        .PreviousSplineId ||
                source.Spline
                    .NextSplineId !=
                    request
                        .NextSplineId ||
                source.Spline
                    .IsHeightSpline !=
                    request
                        .IsHeightSpline ||
                !string.Equals(
                    source.Spline.SplinePath,
                    request.SplinePath,
                    StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidDataException(
                    "splineLinkSourceChanged");
            }

            var states =
                byId.ToDictionary(
                    pair => pair.Key,
                    pair =>
                        new OmsiSplineLinkState(
                            pair.Key,
                            pair.Value
                                .Spline
                                .PreviousSplineId,
                            pair.Value
                                .Spline
                                .NextSplineId));

            var plan =
                OmsiSplineLinkPlanner
                    .Plan(
                        states,
                        request.SplineId,
                        request.PreviousSplineId,
                        request.NextSplineId,
                        request
                            .DesiredPreviousSplineId,
                        request
                            .DesiredNextSplineId);

            if (plan.Count == 0)
            {
                PostMessage(new
                {
                    type = "splineLinksUpdated",
                    map.DirectoryName,
                    splineId =
                        request.SplineId,
                    previousSplineId =
                        request
                            .DesiredPreviousSplineId,
                    nextSplineId =
                        request
                            .DesiredNextSplineId,
                    linksUpdated = 0,
                    filesSaved = 0,
                    backupDirectory =
                        string.Empty
                });

                return;
            }

            var timestamp =
                DateTimeOffset.UtcNow
                    .ToString(
                        "yyyyMMdd-HHmmssfff'Z'",
                        CultureInfo.InvariantCulture);

            var backupRoot =
                Path.Combine(
                    map.DirectoryPath,
                    ".mapstudio-backups",
                    timestamp);

            var writes =
                new List<PendingFileWrite>();

            var editedTilePaths =
                new List<string>();

            var appliedEdits = 0;

            foreach (
                var group in plan.Keys
                    .Select(id => byId[id])
                    .GroupBy(entry =>
                        (
                            TileX: entry.TileX,
                            TileY: entry.TileY,
                            RelativeMapPath:
                                entry.RelativeMapPath)))
            {
                if (!OmsiMapPathResolver
                    .TryResolveTilePath(
                        map.DirectoryPath,
                        group.Key
                            .RelativeMapPath,
                        out var tilePath) ||
                    !File.Exists(tilePath))
                {
                    throw new InvalidDataException(
                        "invalidTilePath");
                }

                var document =
                    await OmsiConfigParser
                        .ParseFileAsync(
                            tilePath);

                var edits =
                    group.Select(entry =>
                    {
                        var target =
                            plan[
                                entry.Spline
                                    .SplineId];

                        return new OmsiSplineLinkEdit(
                            entry.Spline
                                .SourceSectionOrdinal,
                            entry.Spline
                                .SplinePath,
                            entry.Spline
                                .SplineId,
                            entry.Spline
                                .PreviousSplineId,
                            entry.Spline
                                .NextSplineId,
                            entry.Spline
                                .IsHeightSpline,
                            target
                                .PreviousSplineId,
                            target
                                .NextSplineId);
                    })
                    .ToArray();

                var result =
                    OmsiTileSplineLinkEditor
                        .ApplyLinks(
                            document,
                            edits);

                var relativePath =
                    Path.GetRelativePath(
                        map.DirectoryPath,
                        tilePath);

                if (
                    relativePath.StartsWith(
                        "..",
                        StringComparison.Ordinal) ||
                    Path.IsPathRooted(
                        relativePath))
                {
                    throw new InvalidDataException(
                        "invalidTilePath");
                }

                writes.Add(
                    new PendingFileWrite(
                        tilePath,
                        Path.Combine(
                            backupRoot,
                            relativePath),
                        result.Bytes));

                editedTilePaths.Add(
                    tilePath);

                appliedEdits +=
                    result.AppliedEdits;
            }

            await SafeFileTransaction
                .WriteAllAsync(
                    writes);

            foreach (var tilePath in
                editedTilePaths)
            {
                _tileContentCache
                    .TryRemove(
                        tilePath,
                        out _);
            }

            PostMessage(new
            {
                type =
                    "splineLinksUpdated",
                map.DirectoryName,
                splineId =
                    request.SplineId,
                previousSplineId =
                    request
                        .DesiredPreviousSplineId,
                nextSplineId =
                    request
                        .DesiredNextSplineId,
                linksUpdated =
                    appliedEdits,
                filesSaved =
                    writes.Count,
                backupDirectory =
                    backupRoot
            });
        }
        catch (InvalidDataException exception)
        {
            var code =
                exception.Message switch
                {
                    "splineLinkTargetBusy" =>
                        "splineLinkTargetBusy",
                    "splineLinkNeighborMissing" =>
                        "splineLinkTargetMissing",
                    "splineLinkSelf" =>
                        "splineLinkInvalid",
                    "splineLinkDuplicateNeighbor" =>
                        "splineLinkInvalid",
                    _ =>
                        "splineLinkConflict"
                };

            PostMessage(new
            {
                type = "hostError",
                code,
                detail = exception.Message
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = map.DirectoryPath
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "splineLinkError",
                detail = exception.Message
            });
        }
    }

    private async Task SaveSplineTransformsAsync(
        string? directoryName,
        IReadOnlyList<SplineTransformRequest> requests)
    {
        if (
            string.IsNullOrWhiteSpace(
                directoryName) ||
            !_knownMaps.TryGetValue(
                directoryName,
                out var map))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownMap"
            });

            return;
        }

        if (requests.Count == 0)
        {
            PostInvalidMessage();
            return;
        }

        try
        {
            var timestamp =
                DateTimeOffset.UtcNow
                    .ToString(
                        "yyyyMMdd-HHmmssfff'Z'",
                        CultureInfo.InvariantCulture);

            var backupRoot =
                Path.Combine(
                    map.DirectoryPath,
                    ".mapstudio-backups",
                    timestamp);

            var writes =
                new List<PendingFileWrite>();

            var editedTilePaths =
                new List<string>();

            var appliedEdits = 0;

            foreach (
                var group in requests
                    .GroupBy(request =>
                        (
                            request.TileX,
                            request.TileY)))
            {
                var tile =
                    map.Tiles.FirstOrDefault(
                        candidate =>
                            candidate.X ==
                                group.Key.TileX &&
                            candidate.Y ==
                                group.Key.TileY);

                if (tile is null)
                {
                    throw new InvalidDataException(
                        "unknownTile");
                }

                if (!OmsiMapPathResolver
                    .TryResolveTilePath(
                        map.DirectoryPath,
                        tile.RelativeMapPath,
                        out var tilePath))
                {
                    throw new InvalidDataException(
                        "invalidTilePath");
                }

                var document =
                    await OmsiConfigParser
                        .ParseFileAsync(
                            tilePath);

                var edits =
                    group.Select(
                        request =>
                            new OmsiSplineTransformEdit(
                                request.SourceSectionOrdinal,
                                request.SplinePath,
                                request.SplineId,
                                request.PreviousSplineId,
                                request.NextSplineId,
                                request.IsHeightSpline,
                                request.X,
                                request.Z,
                                request.Y,
                                request.Rotation,
                                request.Length,
                                request.Radius,
                                request.GradientStart,
                                request.GradientEnd))
                    .ToArray();

                var result =
                    OmsiTileSplineEditor
                        .ApplyTransforms(
                            document,
                            edits);

                var relativePath =
                    Path.GetRelativePath(
                        map.DirectoryPath,
                        tilePath);

                if (
                    relativePath.StartsWith(
                        "..",
                        StringComparison.Ordinal) ||
                    Path.IsPathRooted(
                        relativePath))
                {
                    throw new InvalidDataException(
                        "invalidTilePath");
                }

                writes.Add(
                    new PendingFileWrite(
                        tilePath,
                        Path.Combine(
                            backupRoot,
                            relativePath),
                        result.Bytes));

                editedTilePaths.Add(
                    tilePath);

                appliedEdits +=
                    result.AppliedEdits;
            }

            await SafeFileTransaction
                .WriteAllAsync(
                    writes);

            foreach (var tilePath in
                editedTilePaths)
            {
                _tileContentCache
                    .TryRemove(
                        tilePath,
                        out _);
            }

            PostMessage(new
            {
                type =
                    "splineTransformsSaved",
                map.DirectoryName,
                editsSaved =
                    appliedEdits,
                filesSaved =
                    writes.Count,
                backupDirectory =
                    backupRoot
            });
        }
        catch (InvalidDataException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "saveConflict",
                detail = exception.Message
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = map.DirectoryPath
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "saveError",
                detail = exception.Message
            });
        }
    }

    private async Task LoadMapFullAsync(
        string? directoryName)
    {
        if (string.IsNullOrWhiteSpace(directoryName) ||
            !_knownMaps.TryGetValue(
                directoryName,
                out var map))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownMap"
            });

            return;
        }

        try
        {
            var requestedTiles =
                map.Tiles.ToArray();

            var totalTiles =
                requestedTiles.Length;

            PostMessage(new
            {
                type = "mapFullLoadingStarted",
                map.DirectoryName,
                totalTiles
            });

            using var semaphore =
                new SemaphoreSlim(
                    Math.Min(
                        MaxConcurrentTileReads,
                        Math.Max(
                            1,
                            Environment.ProcessorCount)));

            var completedTiles = 0;

            var tasks = requestedTiles
                .Select(async (tile, index) =>
                {
                    await semaphore.WaitAsync();

                    try
                    {
                        var content =
                            OmsiMapPathResolver
                                .TryResolveTilePath(
                                    map.DirectoryPath,
                                    tile.RelativeMapPath,
                                    out var tilePath)
                            ? await ReadTileCachedAsync(
                                tilePath)
                            : OmsiTileContent.Missing;

                        var completed =
                            Interlocked.Increment(
                                ref completedTiles);

                        if (
                            completed == totalTiles ||
                            completed % 8 == 0)
                        {
                            PostMessage(new
                            {
                                type = "mapFullLoadingProgress",
                                map.DirectoryName,
                                completedTiles = completed,
                                totalTiles
                            });
                        }

                        return (
                            Index: index,
                            Tile: tile,
                            Content: content);
                    }
                    finally
                    {
                        semaphore.Release();
                    }
                })
                .ToArray();

            var loadedTiles =
                await Task.WhenAll(tasks);

            var objects = new List<object>();
            var splines = new List<object>();

            foreach (var loaded in loadedTiles
                .OrderBy(result => result.Index))
            {
                foreach (var placedObject in
                    loaded.Content.Objects)
                {
                    _knownSceneryObjectPaths.TryAdd(
                        placedObject.SceneryObjectPath,
                        0);

                    objects.Add(new
                    {
                        tileX = loaded.Tile.X,
                        tileY = loaded.Tile.Y,
                        placedObject.HeaderValue,
                        placedObject.SceneryObjectPath,
                        placedObject.ObjectId,
                        placedObject.SourceSectionOrdinal,
                        placedObject.X,
                        placedObject.Y,
                        placedObject.Z,
                        placedObject.Rotation,
                        placedObject.Pitch,
                        placedObject.Bank
                    });
                }

                foreach (var placedSpline in
                    loaded.Content.Splines)
                {
                    _knownSplinePaths.TryAdd(
                        placedSpline.SplinePath,
                        0);

                    splines.Add(new
                    {
                        tileX = loaded.Tile.X,
                        tileY = loaded.Tile.Y,
                        placedSpline.HeaderValue,
                        placedSpline.SplinePath,
                        placedSpline.SplineId,
                        placedSpline.SourceSectionOrdinal,
                        placedSpline.PreviousSplineId,
