    private async Task LoadTextureAssetAsync(
        string requestKey,
        string fullPath)
    {
        try
        {
            var info =
                new FileInfo(fullPath);

            if (
                !info.Exists ||
                info.Length >
                    MaxTextureAssetBytes)
            {
                PostMissingTextureAsset(
                    requestKey,
                    info.Exists
                        ? "textureTooLarge"
                        : "textureNotFound");
                return;
            }

            var bytes =
                await File.ReadAllBytesAsync(
                    fullPath);

            var extension =
                Path.GetExtension(fullPath)
                    .ToLowerInvariant();

            PostMessage(new
            {
                type = "textureAssetLoaded",
                requestKey,
                asset = new
                {
                    exists = true,
                    base64Data =
                        Convert.ToBase64String(
                            bytes),
                    extension,
                    mimeType =
                        GetTextureMimeType(
                            extension),
                    errorCode =
                        (string?)null
                }
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMissingTextureAsset(
                requestKey,
                "accessDenied");
        }
        catch (IOException)
        {
            PostMissingTextureAsset(
                requestKey,
                "textureReadError");
        }
    }

    private void PostMissingTextureAsset(
        string? requestKey,
        string errorCode)
    {
        if (string.IsNullOrWhiteSpace(
                requestKey))
        {
            return;
        }

        PostMessage(new
        {
            type = "textureAssetLoaded",
            requestKey,
            asset = new
            {
                exists = false,
                base64Data =
                    (string?)null,
                extension =
                    (string?)null,
                mimeType =
                    (string?)null,
                errorCode
            }
        });
    }

    private static string
        GetTextureMimeType(
            string extension) =>
        extension.ToLowerInvariant() switch
        {
            ".bmp" => "image/bmp",
            ".gif" => "image/gif",
            ".jpeg" => "image/jpeg",
            ".jpg" => "image/jpeg",
            ".png" => "image/png",
            ".webp" => "image/webp",
            ".dds" =>
                "application/octet-stream",
            ".tga" =>
                "application/octet-stream",
            _ =>
                "application/octet-stream"
        };

