    private async Task LoadSceneryObjectGeometryAsync(
        string? sceneryObjectPath)
    {
        if (_omsiRootPath is null ||
            string.IsNullOrWhiteSpace(sceneryObjectPath) ||
            !_knownSceneryObjectPaths.ContainsKey(
                sceneryObjectPath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "unknownSceneryObject"
            });
            return;
        }

        if (!OmsiSceneryObjectPathResolver.TryResolve(
                _omsiRootPath,
                sceneryObjectPath,
                out var sceneryObjectFullPath))
        {
            PostMessage(new
            {
                type = "hostError",
                code = "invalidSceneryObjectPath"
            });
            return;
        }

        try
        {
            var metadata =
                await _sceneryObjectReader.ReadMetadataAsync(
                    sceneryObjectFullPath);

            var meshes = new List<object>(
                metadata.MeshPaths.Count);

            for (
                var meshOrdinal = 0;
                meshOrdinal <
                    metadata.MeshPaths.Count;
                meshOrdinal++)
            {
                var declaredPath =
                    metadata.MeshPaths[
                        meshOrdinal];

                var lodThreshold =
                    metadata.MeshLodThresholds
                        .Count >
                    meshOrdinal
                        ? metadata
                            .MeshLodThresholds[
                                meshOrdinal]
                        : null;

                var materialOverrides =
                    metadata.MaterialOverrides
                        .Where(
                            material =>
                                material
                                    .MeshOrdinal ==
                                meshOrdinal)
                        .ToArray();

                if (!OmsiSceneryMeshPathResolver.TryResolve(
                        _omsiRootPath,
                        sceneryObjectFullPath,
                        declaredPath,
                        out var meshFullPath))
                {
                    meshes.Add(new
                    {
                        declaredPath,
                        lodThreshold,
                        materialOverrides,
                        geometry =
                            OmsiO3dGeometry.Error(
                                "invalidMeshPath")
                    });
                    continue;
                }

                if (!string.Equals(
                        Path.GetExtension(meshFullPath),
                        ".o3d",
                        StringComparison.OrdinalIgnoreCase))
                {
                    meshes.Add(new
                    {
                        declaredPath,
                        lodThreshold,
                        materialOverrides,
                        geometry =
                            OmsiO3dGeometry.Error(
                                "unsupportedFormat")
                    });
                    continue;
                }

                meshes.Add(new
                {
                    declaredPath,
                    lodThreshold,
                    materialOverrides,
                    geometry =
                        _o3dGeometryReader.Read(
                            meshFullPath)
                });
            }

            PostMessage(new
            {
                type = "sceneryObjectGeometryLoaded",
                sceneryObjectPath,
                geometry = new
                {
                    meshes
                }
            });
        }
        catch (UnauthorizedAccessException)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "accessDenied",
                detail = sceneryObjectPath
            });
        }
        catch (IOException exception)
        {
            PostMessage(new
            {
                type = "hostError",
                code = "ioError",
                detail = exception.Message
            });
        }
    }

    private async Task<IReadOnlyList<object>>
        CreateMeshReferencesAsync(
            string omsiRoot,
            string sceneryObjectFullPath,
            IReadOnlyList<string> declaredPaths)
    {
        var results =
            new List<object>(
                declaredPaths.Count);

        foreach (var declaredPath in declaredPaths)
        {
            var resolved =
                OmsiSceneryMeshPathResolver.TryResolve(
                    omsiRoot,
                    sceneryObjectFullPath,
                    declaredPath,
                    out var fullPath);

            var fileExists =
                resolved &&
                File.Exists(fullPath);

            OmsiO3dHeader? o3d = null;
            OmsiO3dStructureSummary? structure = null;

            if (fileExists &&
                string.Equals(
                    Path.GetExtension(fullPath),
                    ".o3d",
                    StringComparison.OrdinalIgnoreCase))
            {
                o3d =
                    await _o3dHeaderReader.ReadAsync(
                        fullPath);

                if (o3d.IsValid)
                {
                    structure =
                        _o3dStructureReader.Read(
                            fullPath);
                }
            }

            results.Add(new
            {
                declaredPath,
                fileExists,
                o3d,
                structure
            });
        }

        return results;
    }

    private static bool TryReadObjectTransformRequests(
        JsonElement element,
        out IReadOnlyList<ObjectTransformRequest> requests)
    {
        requests =
            Array.Empty<ObjectTransformRequest>();

        if (
            !element.TryGetProperty(
                "edits",
                out var editsElement) ||
            editsElement.ValueKind !=
                JsonValueKind.Array)
        {
            return false;
        }

        var result =
            new List<ObjectTransformRequest>();

        foreach (var edit in
            editsElement.EnumerateArray())
        {
            if (
                !TryReadInt32(
                    edit,
                    "tileX",
                    out var tileX) ||
                !TryReadInt32(
                    edit,
                    "tileY",
                    out var tileY) ||
                !TryReadInt32(
                    edit,
                    "sourceSectionOrdinal",
                    out var sourceSectionOrdinal) ||
                !TryReadString(
                    edit,
                    "sceneryObjectPath",
                    out var sceneryObjectPath) ||
                !TryReadInt32(
                    edit,
                    "objectId",
                    out var objectId) ||
                !TryReadDouble(
                    edit,
                    "x",
                    out var x) ||
                !TryReadDouble(
                    edit,
                    "y",
                    out var y) ||
                !TryReadDouble(
                    edit,
                    "z",
                    out var z) ||
                !TryReadDouble(
                    edit,
                    "rotation",
                    out var rotation) ||
                !TryReadDouble(
                    edit,
                    "pitch",
                    out var pitch) ||
                !TryReadDouble(
                    edit,
                    "bank",
                    out var bank))
            {
                return false;
            }

            result.Add(
                new ObjectTransformRequest(
                    tileX,
                    tileY,
                    sourceSectionOrdinal,
                    sceneryObjectPath!,
                    objectId,
                    x,
                    y,
                    z,
                    rotation,
                    pitch,
                    bank));
        }

        requests = result;
        return result.Count > 0;
    }

