                "z",
                out var z) ||
            !TryReadDouble(
                element,
                "rotation",
                out var rotation) ||
            !TryReadDouble(
                element,
                "length",
                out var length) ||
            length < 0 ||
            !TryReadDouble(
                element,
                "radius",
                out var radius) ||
            !TryReadDouble(
                element,
                "gradientStart",
                out var gradientStart) ||
            !TryReadDouble(
                element,
                "gradientEnd",
                out var gradientEnd))
        {
            return false;
        }

        request =
            new SplineInsertionRequest(
                directoryName!,
                sourceTileX,
                sourceTileY,
                sourceSectionOrdinal,
                splinePath!,
                splineId,
                previousSplineId,
                nextSplineId,
                isHeightSpline,
                targetTileX,
                targetTileY,
                x,
                y,
                z,
                rotation,
                length,
                radius,
                gradientStart,
                gradientEnd);

        return true;
    }

    private static bool TryReadSplineTransformRequests(
        JsonElement element,
        out IReadOnlyList<SplineTransformRequest> requests)
    {
        requests =
            Array.Empty<SplineTransformRequest>();

        if (
            !element.TryGetProperty(
                "edits",
                out var editsElement) ||
            editsElement.ValueKind !=
                JsonValueKind.Array)
        {
            return false;
        }

        var result =
            new List<SplineTransformRequest>();

        foreach (var edit in
            editsElement.EnumerateArray())
        {
            if (
                !TryReadInt32(
                    edit,
                    "tileX",
                    out var tileX) ||
                !TryReadInt32(
                    edit,
                    "tileY",
                    out var tileY) ||
                !TryReadInt32(
                    edit,
                    "sourceSectionOrdinal",
                    out var sourceSectionOrdinal) ||
                !TryReadString(
                    edit,
                    "splinePath",
                    out var splinePath) ||
                !TryReadInt32(
                    edit,
                    "splineId",
                    out var splineId) ||
                !TryReadInt32(
                    edit,
                    "previousSplineId",
                    out var previousSplineId) ||
                !TryReadInt32(
                    edit,
                    "nextSplineId",
                    out var nextSplineId) ||
                !TryReadBoolean(
                    edit,
                    "isHeightSpline",
                    out var isHeightSpline) ||
                !TryReadDouble(
                    edit,
                    "x",
                    out var x) ||
                !TryReadDouble(
                    edit,
                    "z",
                    out var z) ||
                !TryReadDouble(
                    edit,
                    "y",
                    out var y) ||
                !TryReadDouble(
                    edit,
                    "rotation",
                    out var rotation) ||
                !TryReadDouble(
                    edit,
                    "length",
                    out var length) ||
                !TryReadDouble(
                    edit,
                    "radius",
                    out var radius) ||
                !TryReadDouble(
                    edit,
                    "gradientStart",
                    out var gradientStart) ||
                !TryReadDouble(
                    edit,
                    "gradientEnd",
                    out var gradientEnd))
            {
                return false;
            }

            result.Add(
                new SplineTransformRequest(
                    tileX,
                    tileY,
                    sourceSectionOrdinal,
                    splinePath!,
                    splineId,
                    previousSplineId,
                    nextSplineId,
                    isHeightSpline,
                    x,
                    z,
                    y,
                    rotation,
                    length,
                    radius,
                    gradientStart,
                    gradientEnd));
        }

        requests = result;
        return result.Count > 0;
    }

    private static bool TryReadBoolean(
        JsonElement element,
        string propertyName,
        out bool value)
    {
        value = false;

        if (!element.TryGetProperty(
                propertyName,
                out var property))
        {
            return false;
        }

        if (
            property.ValueKind ==
                JsonValueKind.True)
        {
            value = true;
            return true;
        }

        if (
            property.ValueKind ==
                JsonValueKind.False)
        {
            return true;
        }

        return false;
    }

    private static bool TryReadDouble(
        JsonElement element,
        string propertyName,
        out double value)
    {
        value = 0;

        return element.TryGetProperty(
                propertyName,
                out var property) &&
            property.ValueKind ==
                JsonValueKind.Number &&
            property.TryGetDouble(
                out value) &&
            double.IsFinite(value);
    }

    private sealed record MapInsertionSnapshot(
        IReadOnlyList<OmsiTileContent> Contents,
        int MaxUsedId);

