        int TileX,
        int TileY,
        int SourceSectionOrdinal,
        string SplinePath,
        int SplineId,
        int PreviousSplineId,
        int NextSplineId,
        bool IsHeightSpline,
        int DesiredPreviousSplineId,
        int DesiredNextSplineId);

    private sealed record SplineInsertionRequest(
        string DirectoryName,
        int SourceTileX,
        int SourceTileY,
        int SourceSectionOrdinal,
        string SplinePath,
        int SplineId,
        int PreviousSplineId,
        int NextSplineId,
        bool IsHeightSpline,
        int TargetTileX,
        int TargetTileY,
        double X,
        double Y,
        double Z,
        double Rotation,
        double Length,
        double Radius,
        double GradientStart,
        double GradientEnd);

    private sealed record SplineTransformRequest(
        int TileX,
        int TileY,
        int SourceSectionOrdinal,
        string SplinePath,
        int SplineId,
        int PreviousSplineId,
        int NextSplineId,
        bool IsHeightSpline,
        double X,
        double Z,
        double Y,
        double Rotation,
        double Length,
        double Radius,
        double GradientStart,
        double GradientEnd);

    private sealed class InlineProgress<T>(
        Action<T> handler) : IProgress<T>
    {
        public void Report(T value) =>
            handler(value);
    }

    private static bool TryReadInt32(
        JsonElement element,
        string propertyName,
        out int value)
    {
        value = 0;

        return element.TryGetProperty(
                propertyName,
                out var property) &&
            property.ValueKind ==
                JsonValueKind.Number &&
            property.TryGetInt32(
                out value);
    }

    private static bool TryReadString(
        JsonElement element,
        string propertyName,
        out string? value)
    {
        value = null;

        if (!element.TryGetProperty(
                propertyName,
                out var property) ||
            property.ValueKind != JsonValueKind.String)
        {
            return false;
        }

        value = property.GetString();

        return !string.IsNullOrWhiteSpace(value);
    }

    private void PostInvalidMessage()
    {
        PostMessage(new
        {
            type = "hostError",
            code = "invalidMessage"
        });
    }

    private void PostMessage(object payload)
    {
        var json =
            JsonSerializer.Serialize(
                payload,
                _jsonOptions);

        EditorWebView.CoreWebView2
            .PostWebMessageAsJson(json);
    }
}

