const getObjectName = (path: string) =>
  path.split(/[\\/]/).filter(Boolean).at(-1) ?? path;

const formatFileSize = (
  bytes: number
) => {
  if (bytes >= 1024 * 1024) {
    return `${(
      bytes /
      (1024 * 1024)
    ).toFixed(1)} MiB`;
  }

  if (bytes >= 1024) {
    return `${(
      bytes / 1024
    ).toFixed(1)} KiB`;
  }

  return `${bytes} B`;
};

const normalizeTextureFileName = (
  value: string
) =>
  value
    .replace(/\\/g, "/")
    .split("/")
    .at(-1)
    ?.toLocaleLowerCase("en-US") ??
  value.toLocaleLowerCase("en-US");

const findSceneryMaterialOverride = (
  mesh:
    OmsiSceneryObjectGeometry["meshes"][number],
  materialIndex: number
) => {
  const textureName =
    mesh.geometry.materials[
      materialIndex
    ]?.textureName;

  if (!textureName) {
    return undefined;
  }

  const normalized =
    normalizeTextureFileName(
      textureName
    );

  return mesh.materialOverrides.find(
    (override) =>
      override.materialIndex ===
        materialIndex &&
      normalizeTextureFileName(
        override.textureName
      ) === normalized
  );
};

