  useEffect(() => {
    if (!bridgeAvailable) {
      return;
    }

    const sceneryObjectPath =
      selectedObject
        ?.sceneryObjectPath ??
      placementAsset
        ?.sceneryObjectPath;

    if (!sceneryObjectPath) {
      return;
    }

    const geometry =
      geometryByPath[
        sceneryObjectPath
      ];

    if (!geometry) {
      return;
    }

    const requests:
      Array<{
        key: string;
        meshPath: string;
        textureName: string;
      }> = [];

    const queuedKeys =
      new Set<string>();

    const queueTexture = (
      meshPath: string,
      textureName:
        | string
        | null
        | undefined
    ) => {
      if (!textureName) {
        return;
      }

      const key =
        getSceneryTextureAssetKey(
          sceneryObjectPath,
          meshPath,
          textureName
        );

      if (
        queuedKeys.has(key) ||
        Object.hasOwn(
          textureAssetsByKey,
          key
        ) ||
        Object.hasOwn(
          requestedTextureKeys,
          key
        )
      ) {
        return;
      }

      queuedKeys.add(key);

      requests.push({
        key,
        meshPath,
        textureName
      });
    };

    for (const mesh of
      geometry.meshes) {
      for (const [
        materialIndex,
        material
      ] of mesh.geometry.materials
        .entries()) {
        queueTexture(
          mesh.declaredPath,
          material.textureName
        );

        const materialOverride =
          findSceneryMaterialOverride(
            mesh,
            materialIndex
          );

        queueTexture(
          mesh.declaredPath,
          materialOverride
            ?.bumpMapTextureName
        );

        queueTexture(
          mesh.declaredPath,
          materialOverride
            ?.environmentMapTextureName
        );

        if (nightPreviewEnabled) {
          queueTexture(
            mesh.declaredPath,
            materialOverride
              ?.nightMapTextureName
          );
        }
      }
    }

    if (requests.length === 0) {
      return;
    }

    setRequestedTextureKeys(
      (current) => {
        const next = {
          ...current
        };

        for (const request of
          requests) {
          next[request.key] = true;
        }

        return next;
      }
    );

    for (const request of
      requests) {
      loadSceneryTextureAsset(
        request.key,
        sceneryObjectPath,
        request.meshPath,
        request.textureName
      );
    }
  }, [
    bridgeAvailable,
    geometryByPath,
    nightPreviewEnabled,
    placementAsset,
    requestedTextureKeys,
    selectedObject,
    textureAssetsByKey
  ]);

  useEffect(() => {
    if (!bridgeAvailable) {
      return;
    }

    const placedSpline =
      selectedSpline ??
      splinePlacementTemplate;

    if (!placedSpline) {
      return;
    }

    const definition =
      splineProfilesByPath[
        placedSpline.splinePath
      ];

    if (!definition) {
      return;
    }

    const requests =
      definition.textures
        .filter(
          (textureName) =>
            Boolean(textureName)
        )
        .map((textureName) => ({
          textureName,
          key:
            getSplineTextureAssetKey(
              placedSpline.splinePath,
              textureName
            )
        }))
        .filter(
          (request) =>
            !Object.hasOwn(
              textureAssetsByKey,
              request.key
            ) &&
            !Object.hasOwn(
              requestedTextureKeys,
              request.key
            )
        );

    if (requests.length === 0) {
      return;
    }

    setRequestedTextureKeys(
      (current) => {
        const next = {
          ...current
        };

        for (const request of
          requests) {
          next[request.key] = true;
        }

        return next;
      }
    );

    for (const request of
      requests) {
      loadSplineTextureAsset(
        request.key,
        placedSpline.splinePath,
        request.textureName
      );
    }
