    bridgeAvailable,
    requestedTextureKeys,
    selectedSpline,
    splinePlacementTemplate,
    splineProfilesByPath,
    textureAssetsByKey
  ]);

  const objectsForViewport = useMemo(
    () =>
      objects.map(
        (placedObject) =>
          previewObjectTransforms[
            getPlacedObjectKey(
              placedObject
            )
          ] ?? placedObject
      ),
    [
      objects,
      previewObjectTransforms
    ]
  );

  const splinesForViewport = useMemo(
    () =>
      splines.map(
        (placedSpline) =>
          previewSplineTransforms[
            getPlacedSplineKey(
              placedSpline
            )
          ] ?? placedSpline
      ),
    [
      previewSplineTransforms,
      splines
    ]
  );

  const nearbyObjectPaths =
    useMemo(() => {
      const byPath =
        new Map<string, number>();

      for (const placedObject of
        objectsForViewport) {
        const distance =
          activeTile
            ? Math.max(
                Math.abs(
                  placedObject.tileX -
                    activeTile.x
                ),
                Math.abs(
                  placedObject.tileY -
                    activeTile.y
                )
              )
            : 0;

        const current =
          byPath.get(
            placedObject
              .sceneryObjectPath
          );

        if (
          current === undefined ||
          distance < current
        ) {
          byPath.set(
            placedObject
              .sceneryObjectPath,
            distance
          );
        }
      }

      return Array.from(
        byPath.entries()
      )
        .sort(
          (left, right) =>
            left[1] - right[1] ||
            left[0].localeCompare(
              right[0]
            )
        )
        .slice(
          0,
          nearbyObjectPathLimit
        )
        .map(([path]) => path);
    }, [
      activeTile,
      objectsForViewport
    ]);

  const nearbySplinePaths =
    useMemo(() => {
      const byPath =
        new Map<string, number>();

      for (const placedSpline of
        splinesForViewport) {
        const distance =
          activeTile
            ? Math.max(
                Math.abs(
                  placedSpline.tileX -
                    activeTile.x
                ),
                Math.abs(
                  placedSpline.tileY -
                    activeTile.y
                )
              )
            : 0;

        const current =
          byPath.get(
            placedSpline.splinePath
          );

        if (
          current === undefined ||
          distance < current
        ) {
          byPath.set(
            placedSpline.splinePath,
            distance
          );
        }
      }

      return Array.from(
        byPath.entries()
      )
        .sort(
          (left, right) =>
            left[1] - right[1] ||
            left[0].localeCompare(
              right[0]
            )
        )
        .slice(
          0,
          nearbySplinePathLimit
        )
        .map(([path]) => path);
    }, [
      activeTile,
      splinesForViewport
    ]);

  useEffect(() => {
    if (
      !bridgeAvailable ||
      loadingSplineFor ||
      preloadingSplineProfileFor
    ) {
      return;
    }

    const nextPath =
      nearbySplinePaths.find(
