  useEffect(() => {
    if (!bridgeAvailable) {
      return;
    }

    const autoKeys =
      Object.keys(
        autoPrefetchedTextureKeys
      );

    const usedObject =
      autoKeys.filter(
        (key) =>
          key.startsWith(
            "scenery|"
          )
      ).length;

    const usedSpline =
      autoKeys.filter(
        (key) =>
          key.startsWith(
            "spline|"
          )
      ).length;

    const objectBudget =
      Math.min(
        autoObjectTextureBatch,
        Math.max(
          0,
          autoObjectTextureLimit -
            usedObject
        )
      );

    const splineBudget =
      Math.min(
        autoSplineTextureBatch,
        Math.max(
          0,
          autoSplineTextureLimit -
            usedSpline
        )
      );

    const objectRequests:
      Array<{
        kind: "scenery";
        key: string;
        sceneryObjectPath: string;
        meshPath: string;
        textureName: string;
      }> = [];

    for (const sceneryObjectPath of
      nearbyObjectPaths) {
      if (
        objectRequests.length >=
          objectBudget
      ) {
        break;
      }

      const geometry =
        geometryByPath[
          sceneryObjectPath
        ];

      if (!geometry) {
        continue;
      }

      const queuedKeys =
        new Set(
          objectRequests.map(
            (request) =>
              request.key
          )
        );

      const queueObjectTexture = (
        meshPath: string,
        textureName:
          | string
          | null
          | undefined
      ) => {
        if (
          !textureName ||
          objectRequests.length >=
            objectBudget
        ) {
          return;
        }

        const key =
          getSceneryTextureAssetKey(
            sceneryObjectPath,
            meshPath,
            textureName
          );

        if (
          queuedKeys.has(key) ||
          Object.hasOwn(
            textureAssetsByKey,
            key
          ) ||
          Object.hasOwn(
            requestedTextureKeys,
            key
          )
        ) {
          return;
        }

        queuedKeys.add(key);

        objectRequests.push({
          kind: "scenery",
          key,
          sceneryObjectPath,
          meshPath,
          textureName
        });
      };

      for (const mesh of
        geometry.meshes) {
        for (const [
          materialIndex,
          material
        ] of mesh.geometry.materials
          .entries()) {
          if (
            objectRequests.length >=
              objectBudget
          ) {
            break;
          }

          queueObjectTexture(
            mesh.declaredPath,
            material.textureName
          );

          const materialOverride =
            findSceneryMaterialOverride(
              mesh,
              materialIndex
            );

          queueObjectTexture(
            mesh.declaredPath,
            materialOverride
              ?.bumpMapTextureName
          );

          queueObjectTexture(
            mesh.declaredPath,
            materialOverride
              ?.environmentMapTextureName
          );

          if (nightPreviewEnabled) {
            queueObjectTexture(
              mesh.declaredPath,
              materialOverride
                ?.nightMapTextureName
            );
          }
        }
      }
    }

    const splineRequests:
      Array<{
        kind: "spline";
        key: string;
        splinePath: string;
        textureName: string;
      }> = [];

    for (const splinePath of
      nearbySplinePaths) {
      if (
        splineRequests.length >=
          splineBudget
      ) {
        break;
      }

      const definition =
        splineProfilesByPath[
          splinePath
        ];

      if (!definition) {
        continue;
      }

      for (const textureName of
        definition.textures) {
        if (
          splineRequests.length >=
            splineBudget
        ) {
          break;
        }

        if (!textureName) {
          continue;
        }

        const key =
          getSplineTextureAssetKey(
            splinePath,
            textureName
          );

        if (
          Object.hasOwn(
            textureAssetsByKey,
            key
          ) ||
          Object.hasOwn(
            requestedTextureKeys,
            key
          )
        ) {
          continue;
        }

        splineRequests.push({
          kind: "spline",
          key,
          splinePath,
          textureName
        });
      }
    }

