                  Ao salvar, o host exige um
                  template real neutro do mesmo
                  tipo ([spline] ou [spline_h])
                  já existente no mapa para copiar
                  header e extras sem inventar
                  metadados.
                </div>
              </div>
            )}
            </div>
          </aside>

          <section className="editor-viewport">
            <Viewport
              tiles={activeTiles}
              objects={
                objectsForViewport
              }
              splines={
                splinesForViewport
              }
              editorTool={editorTool}
              snapEnabled={snapEnabled}
              moveSnap={moveSnap}
              rotationSnap={
                rotationSnap
              }
              showGrid={showGrid}
              showObjects={showObjects}
              showSplines={showSplines}
              showSplineProfiles={
                showSplineProfiles
              }
              nightPreviewEnabled={
                nightPreviewEnabled
              }
              cameraAction={cameraAction}
              placementAssetPath={
                placementAsset
                  ?.sceneryObjectPath
              }
              placementGeometry={
                placementAsset
                  ? geometryByPath[
                      placementAsset
                        .sceneryObjectPath
                    ]
                  : undefined
              }
              pendingPlacement={
                pendingPlacement
              }
              onPlacementPoint={
                handlePlacementPoint
              }
              splinePlacementTemplate={
                splinePlacementTemplate
              }
              splinePlacementProfile={
                splinePlacementTemplate
                  ? splineProfilesByPath[
                      splinePlacementTemplate
                        .splinePath
                    ]
                  : undefined
              }
              pendingSplinePlacement={
                pendingSplinePlacement
              }
              onSplinePlacementPoint={
                handleSplinePlacementPoint
              }
              activeTile={activeTile}
              onActiveTileChange={
                (tile) => {
                  if (
                    tile.x ===
                      activeTile?.x &&
                    tile.y ===
                      activeTile?.y
                  ) {
                    return;
                  }

                  setActiveTile(tile);

                  if (
                    mapLoadMode ===
                    "performance"
                  ) {
                    setLoadedRegionKey(
                      undefined
                    );
                    setObjects([]);
                    setSplines([]);
                  }

                  setSelectedObject(
                    undefined
                  );
                  setSelectedSpline(
                    undefined
                  );
                }
              }
              usesWorldCoordinates={
                selectedMap.usesWorldCoordinates
              }
              selectedObject={selectedObject}
              selectedGeometry={selectedGeometry}
              objectGeometryByPath={
                geometryByPath
              }
              textureAssetsByKey={
                textureAssetsByKey
              }
              splineProfilesByPath={
                splineProfilesByPath
              }
              selectedSpline={selectedSpline}
              selectedSplineProfile={
                selectedSplineProfile
              }
              onSelectObject={
                handleObjectSelection
              }
              onSelectSpline={
                handleSplineSelection
              }
              onPreviewObjectTransform={
                handlePreviewObjectTransform
              }
              onPreviewSplineTransform={
                handlePreviewSplineTransform
              }
            />

            {splinePlacementTemplate && (
              <div className="placement-bar">
                <div>
                  <strong>
                    {splineLibraryPlacementAsset
                      ? splineLibraryPlacementIsHeight
                        ? "Nova spline de altura: "
                        : "Nova spline: "
                      : "Copiando spline: "}
                    {getObjectName(
                      splinePlacementTemplate
                        .splinePath
                    )}
                  </strong>
                  <span>
                    {pendingSplinePlacement
                      ? `Tile ${pendingSplinePlacement.targetTileX},${pendingSplinePlacement.targetTileY} · X ${formatNumber(pendingSplinePlacement.x)} · Y ${formatNumber(pendingSplinePlacement.y)} · desconectada`
                      : splineLibraryPlacementAsset
                        ? splineLibraryPlacementIsHeight
                          ? "Clique em um tile para posicionar a nova spline de altura."
                          : "Clique em um tile para posicionar a nova spline normal."
                        : "Clique em um tile para posicionar o início da cópia."}
                  </span>
                </div>

                {pendingSplinePlacement && (
                  <>
                    {(
                      [
                        ["z", "Z", 0.1],
                        [
                          "rotation",
                          "Rot °",
                          1
                        ],
                        [
                          "length",
                          "Comp.",
                          0.1
                        ],
                        [
                          "radius",
                          "Raio",
                          0.1
                        ],
                        [
                          "gradientStart",
                          "Grad. I",
                          0.1
                        ],
                        [
                          "gradientEnd",
                          "Grad. F",
                          0.1
                        ]
                      ] as const
                    ).map(
                      ([field, label, step]) => (
                        <label
                          className="placement-field"
                          key={field}
                        >
                          <span>{label}</span>
                          <input
                            type="number"
                            step={step}
                            min={
                              field === "length"
                                ? 0
                                : undefined
                            }
                            value={
                              pendingSplinePlacement[
                                field
                              ]
                            }
                            onChange={(event) => {
                              const value =
                                event.currentTarget
                                  .valueAsNumber;

                              if (
                                Number.isFinite(
                                  value
                                ) &&
                                (
                                  field !==
                                    "length" ||
                                  value >= 0
                                )
                              ) {
                                setPendingSplinePlacement(
                                  (current) =>
                                    current
                                      ? {
                                          ...current,
                                          [field]:
                                            value
                                        }
                                      : current
                                );
                              }
                            }}
                          />
                        </label>
                      )
                    )}
                  </>
                )}

                <button
                  type="button"
                  className="primary-button"
                  disabled={
                    !pendingSplinePlacement ||
                    insertingSpline
                  }
                  onClick={
                    handleConfirmSplinePlacement
                  }
                  title="Criar backup e inserir uma spline desconectada"
                >
                  {insertingSpline
                    ? "Inserindo..."
                    : "Confirmar e salvar"}
                </button>

                <button
                  type="button"
                  className="secondary-action"
                  disabled={insertingSpline}
                  onClick={
                    handleCancelSplinePlacement
                  }
                >
                  Cancelar
                </button>
              </div>
            )}

            {placementAsset && (
              <div className="placement-bar">
                <div>
                  <strong>
                    Colocando:{" "}
                    {placementAsset.fileName}
                  </strong>
                  <span>
                    {pendingPlacement
                      ? `Tile ${pendingPlacement.tileX},${pendingPlacement.tileY} · X ${formatNumber(pendingPlacement.x)} · Y ${formatNumber(pendingPlacement.y)}`
                      : "Clique em um tile para posicionar a prévia."}
                  </span>

                  {mapLoadMode ===
                    "full" &&
                    !placementHasKnownTemplate && (
                    <span className="placement-warning">
                      Prévia apenas: este .sco ainda não existe no mapa, então seus parâmetros extras não podem ser derivados com segurança.
                    </span>
                  )}
                </div>

                {pendingPlacement && (
                  <>
                    <label className="placement-field">
                      <span>Z</span>
                      <input
                        type="number"
                        step="0.1"
                        value={
                          pendingPlacement.z
                        }
                        onChange={(event) => {
                          const value =
                            event.currentTarget
                              .valueAsNumber;

                          if (
                            Number.isFinite(
                              value
                            )
                          ) {
                            setPendingPlacement(
                              (current) =>
                                current
                                  ? {
                                      ...current,
                                      z: value
                                    }
                                  : current
                            );
                          }
                        }}
                      />
                    </label>

                    <label className="placement-field">
                      <span>Rot °</span>
                      <input
                        type="number"
                        step="1"
                        value={
                          pendingPlacement.rotation
                        }
                        onChange={(event) => {
                          const value =
                            event.currentTarget
                              .valueAsNumber;

                          if (
                            Number.isFinite(
                              value
                            )
                          ) {
                            setPendingPlacement(
                              (current) =>
                                current
                                  ? {
                                      ...current,
                                      rotation:
                                        value
                                    }
                                  : current
                            );
                          }
                        }}
                      />
                    </label>

                    <label className="placement-field">
                      <span>Pitch °</span>
                      <input
                        type="number"
                        step="1"
                        value={
                          pendingPlacement.pitch
                        }
                        onChange={(event) => {
                          const value =
                            event.currentTarget
                              .valueAsNumber;

                          if (
                            Number.isFinite(
                              value
                            )
                          ) {
                            setPendingPlacement(
                              (current) =>
                                current
                                  ? {
                                      ...current,
                                      pitch: value
                                    }
                                  : current
                            );
                          }
                        }}
                      />
                    </label>

                    <label className="placement-field">
                      <span>Bank °</span>
                      <input
                        type="number"
                        step="1"
                        value={
                          pendingPlacement.bank
                        }
                        onChange={(event) => {
                          const value =
                            event.currentTarget
                              .valueAsNumber;

                          if (
                            Number.isFinite(
                              value
                            )
                          ) {
                            setPendingPlacement(
                              (current) =>
                                current
                                  ? {
                                      ...current,
                                      bank: value
                                    }
                                  : current
                            );
                          }
                        }}
                      />
                    </label>
                  </>
                )}

                <button
                  type="button"
                  className="primary-button"
                  disabled={
                    !placementCanPersist ||
                    insertingObject
                  }
                  onClick={
                    handleConfirmPlacement
                  }
                  title={
                    placementCanPersist
                      ? "Criar backup e inserir o objeto"
                      : "É necessário um template real do mesmo .sco no mapa"
                  }
                >
                  {insertingObject
                    ? "Inserindo..."
                    : "Confirmar e salvar"}
                </button>

                <button
                  type="button"
                  className="secondary-action"
                  disabled={insertingObject}
                  onClick={
                    handleCancelPlacement
                  }
                >
                  Cancelar
                </button>
              </div>
            )}

            <div className="viewport-toolbar">
              <button
                type="button"
                className={
                  cameraMode ===
                  "perspective"
                    ? "viewport-mode active"
                    : "viewport-mode"
                }
                onClick={() => {
                  setCameraMode(
                    "perspective"
                  );
                  requestCameraAction(
                    "perspective"
                  );
                }}
              >
                Perspectiva · 1
              </button>

              <button
                type="button"
                className={
                  cameraMode === "top"
                    ? "viewport-mode active"
                    : "viewport-mode"
                }
                onClick={() => {
                  setCameraMode("top");
                  requestCameraAction(
                    "top"
                  );
                }}
              >
                Topo · 2
              </button>

              <button
                type="button"
                className={
                  snapEnabled
                    ? "viewport-mode active"
                    : "viewport-mode"
                }
                onClick={() =>
                  setSnapEnabled(
                    (current) =>
                      !current
                  )
                }
                title="Alternar snap (N)"
              >
                Snap · N
              </button>

              <label className="snap-field">
                <span>m</span>
                <input
                  type="number"
                  min="0.01"
                  step="0.1"
                  value={moveSnap}
                  onChange={(event) => {
                    const value =
                      event.currentTarget
                        .valueAsNumber;

                    if (
                      Number.isFinite(
                        value
                      ) &&
                      value > 0
                    ) {
                      setMoveSnap(
                        value
                      );
                    }
                  }}
                />
              </label>

              <label className="snap-field">
                <span>°</span>
                <input
                  type="number"
                  min="0.1"
                  step="1"
                  value={rotationSnap}
                  onChange={(event) => {
                    const value =
                      event.currentTarget
                        .valueAsNumber;

                    if (
                      Number.isFinite(
                        value
                      ) &&
                      value > 0
                    ) {
                      setRotationSnap(
                        value
                      );
                    }
                  }}
                />
              </label>

              <span className="viewport-tool-state">
                Ferramenta:{" "}
                {editorTool === "select"
                  ? "Selecionar"
                  : editorTool === "move"
                    ? "Mover"
                    : "Rotacionar"}
              </span>

              {previewEditCount > 0 && (
                <span className="preview-warning">
                  Prévia objeto ·{" "}
                  {previewEditCount}
                </span>
              )}

              {splinePreviewEditCount > 0 && (
                <span className="preview-warning">
                  Prévia spline ·{" "}
                  {splinePreviewEditCount}
                </span>
              )}
            </div>

            <div className="viewport-layers">
              <label>
                <input
                  type="checkbox"
                  checked={showGrid}
                  onChange={(event) =>
                    setShowGrid(
                      event.target.checked
                    )
                  }
                />
                Grade / tiles
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={showObjects}
                  onChange={(event) =>
                    setShowObjects(
                      event.target.checked
                    )
                  }
                />
                Objetos
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={showSplines}
                  onChange={(event) =>
                    setShowSplines(
                      event.target.checked
                    )
                  }
                />
                Splines
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={
                    showSplineProfiles
                  }
                  disabled={!showSplines}
                  onChange={(event) =>
                    setShowSplineProfiles(
                      event.target.checked
                    )
                  }
                />
                Perfis spline
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={
                    nightPreviewEnabled
                  }
                  onChange={(event) =>
                    setNightPreviewEnabled(
                      event.target.checked
                    )
                  }
                />
                Nightmap
              </label>
              <label className="muted">
                <input
                  type="checkbox"
                  disabled
                />
                Terreno
              </label>

              <button
                type="button"
                className="texture-cache-clear"
                disabled={
                  Object.keys(
                    textureAssetsByKey
                  ).length === 0 &&
                  Object.keys(
                    requestedTextureKeys
                  ).length === 0
                }
                onClick={() => {
                  setTextureAssetsByKey({});
                  setRequestedTextureKeys({});
                  setAutoPrefetchedTextureKeys(
                    {}
                  );
                  textureCacheOrderRef.current =
                    [];
                }}
                title="Limpar texturas carregadas e reiniciar o orçamento automático"
              >
                Limpar cache
              </button>
            </div>

            {(loadingFullMap ||
              Boolean(loadingRegionKey)) && (
              <div className="viewport-loading">
                {loadingFullMap
                  ? `Carregando mapa completo${fullMapProgress ? ` · ${fullMapProgress.completed}/${fullMapProgress.total} tiles` : ""}...`
                  : "Carregando área ativa..."}
              </div>
            )}
          </section>

          <aside className="object-inspector">
            <div className="inspector-heading">
              <strong>Inspetor</strong>
              <span>
                {selectedObject
                  ? "Objeto selecionado"
                  : selectedSpline
                    ? "Spline selecionada"
                    : "Mapa aberto"}
              </span>
            </div>

            {selectedSpline
              ? renderSplineInspector()
              : renderObjectInspector()}
          </aside>
        </div>

        <footer className="editor-statusbar">
          <span>
            {error
              ? "Erro"
              : insertingObject
                ? "Inserindo objeto com backup..."
                : saving
                  ? "Salvando com backup..."
                : saveNotice
                  ? saveNotice
                  : loadingFullMap
                ? "Carregando mapa completo..."
                : Boolean(loadingRegionKey)
                  ? "Carregando área..."
                : preloadingGeometryFor
                  ? `Carregando modelos O3D ${loadedMapGeometryCount}/${mapObjectPaths.length}...`
                  : loadingSplineFor
                    ? "Lendo SLI..."
                  : preloadingSplineProfileFor
                    ? "Preparando perfis SLI próximos..."
                  : loadingMetadataFor
                    ? "Lendo SCO..."
                    : loadingGeometryFor
                    ? "Lendo geometria..."
                    : "Pronto"}
          </span>

          <span>
            Modo:{" "}
            {mapLoadMode === "full"
              ? "Mapa completo"
              : "Desempenho 3×3"}
            <b>·</b>
            Objetos:{" "}
            {selectedStats?.objects ??
              objects.length}
            <b>·</b>
            Splines:{" "}
            {selectedStats?.splines ??
              splines.length}
            <b>·</b>
            O3D:{" "}
            {mapLoadMode === "full"
              ? `${loadedMapGeometryCount}/${mapObjectPaths.length}`
              : "sob demanda"}
            <b>·</b>
            Perfis SLI:{" "}
            {Object.keys(
              splineProfilesByPath
            ).length}
            <b>·</b>
            Texturas auto:{" "}
            {Object.keys(
              autoPrefetchedTextureKeys
            ).length}/
            {autoTextureLimit}
            <b>·</b>
            Cache:{" "}
            {Object.keys(
              textureAssetsByKey
            ).length}/
            {maxTextureCacheEntries}
            <b>·</b>
            Prévia:{" "}
            {previewEditCount}
            <b>·</b>
            Tiles:{" "}
            {activeTiles.length}/
            {selectedMap.tiles.length}
          </span>
        </footer>
      </section>
    );
  };

  const renderPlaceholder = (
    title: string,
    description: string
  ) => (
    <section className="page-shell">
      <div className="page-title compact">
        <span className="eyebrow">
          EM DESENVOLVIMENTO
        </span>
        <h1>{title}</h1>
        <p>{description}</p>
      </div>

      <article className="placeholder-card">
        <strong>
          Ainda não disponível nesta alpha
        </strong>
        <span>
          A interface já reserva este espaço,
          mas nenhum estado fictício será usado.
        </span>
      </article>
    </section>
  );

  return (
    <main className="studio-shell">
      {renderNav()}

      <section className="studio-main">
        <header className="studio-topbar">
          <div className="topbar-tagline">
            <span>CRIAR</span>
            <b>·</b>
            <span>EDITAR</span>
            <b>·</b>
            <span>EXPLORAR</span>
          </div>

          <div className="topbar-state">
            {selectedMap ? (
              <>
                <span className="state-dot" />
                {selectedMap.displayName}
              </>
            ) : rootPath ? (
              "OMSI conectado"
            ) : (
              "Nenhum projeto aberto"
            )}
          </div>
        </header>

        {error && view !== "editor" && (
          <div className="global-error">
            {error}
          </div>
        )}

        <div className="studio-content">
          {view === "home" &&
            renderHome()}
          {view === "omsi" &&
            renderOmsiPage()}
          {view === "map" &&
            renderMapPage()}
          {view === "editor" &&
            renderEditor()}
          {view === "tools" &&
            renderPlaceholder(
              "Ferramentas",
              "Ferramentas de construção e diagnóstico serão ativadas conforme o Core ganhar suporte real."
            )}
          {view === "settings" &&
            renderPlaceholder(
              "Configurações",
              "Preferências do editor, idioma e opções visuais ainda serão implementadas."
            )}
        </div>
      </section>
    </main>
  );
}

export type SceneryLibraryEntry = {
  sceneryObjectPath: string;
  fileName: string;
};

export type SplineLibraryEntry = {
  splinePath: string;
  fileName: string;
};

export type OmsiTile = {
  x: number;
  y: number;
  relativeMapPath: string;
  detailsLoaded: boolean;
  fileExists: boolean;
  objectCount: number;
  splineCount: number;
  splineAttachmentCount: number;
  terrainMarkerPresent: boolean;
  terrainFileExists: boolean;
  terrainFileSize: number;
};

export type OmsiMap = {
  directoryName: string;
  displayName: string;
  directoryPath: string;
  globalConfigPath: string;
  usesWorldCoordinates: boolean;
  tiles: OmsiTile[];
};

export type OmsiPlacedObject = {
  tileX: number;
  tileY: number;
  headerValue: string;
  sceneryObjectPath: string;
  objectId: number;
  sourceSectionOrdinal: number;
  x: number;
  y: number;
  z: number;
  rotation: number;
  pitch: number;
  bank: number;
};

export type OmsiPlacedSpline = {
  tileX: number;
  tileY: number;
  headerValue: string;
  splinePath: string;
  splineId: number;
  sourceSectionOrdinal: number;
  previousSplineId: number;
  nextSplineId: number;
  x: number;
  z: number;
  y: number;
  rotation: number;
  length: number;
  radius: number;
  gradientStart: number;
  gradientEnd: number;
  isHeightSpline: boolean;
};

export type OmsiSplineProfilePoint = {
  x: number;
  z: number;
  textureX: number;
  textureScale: number;
};

export type OmsiSplineSurface = {
  textureIndex: number;
  textureName: string | null;
  from: OmsiSplineProfilePoint;
  to: OmsiSplineProfilePoint;
};

export type OmsiSplineDefinition = {
  exists: boolean;
  textures: string[];
  surfaces: OmsiSplineSurface[];
};

export type OmsiO3dHeader = {
  exists: boolean;
  isValid: boolean;
  version: number | null;
  hasExtendedHeader: boolean;
  usesLongTriangleIndices: boolean;
  usesAlternativeEncryptionSeed: boolean;
  isEncrypted: boolean;
};

export type OmsiO3dStructureSummary = {
  isParsed: boolean;
  vertexCount: number;
  triangleCount: number;
  materialCount: number;
  boneCount: number;
  hasTransform: boolean;
  errorCode: string | null;
};

export type OmsiSceneryMeshReference = {
  declaredPath: string;
  fileExists: boolean;
  o3d: OmsiO3dHeader | null;
  structure: OmsiO3dStructureSummary | null;
};

export type OmsiSceneryObjectMetadata = {
  exists: boolean;
  friendlyName: string | null;
  groups: string[];
  meshes: OmsiSceneryMeshReference[];
  collisionMeshes: OmsiSceneryMeshReference[];
};

export type OmsiO3dMaterial = {
  diffuseR: number;
  diffuseG: number;
  diffuseB: number;
  diffuseA: number;
  specularR: number;
  specularG: number;
  specularB: number;
  emissionR: number;
  emissionG: number;
  emissionB: number;
  specularPower: number;
  textureName: string | null;
};

export type OmsiO3dGeometry = {
  isLoaded: boolean;
  errorCode: string | null;
  positions: number[];
  normals: number[];
  uvs: number[];
  indices: number[];
  triangleMaterialIndices: number[];
  materials: OmsiO3dMaterial[];
};

export type OmsiTextureAsset = {
  exists: boolean;
  base64Data: string | null;
  extension: string | null;
  mimeType: string | null;
  errorCode: string | null;
};

export type OmsiSceneryMaterialOverride = {
  meshOrdinal: number;
  textureName: string;
  materialIndex: number;
  alphaMode: number | null;
  noZWrite: boolean;
  noZCheck: boolean;
  bumpMapTextureName: string | null;
  bumpMapStrength: number | null;
  nightMapTextureName: string | null;
  environmentMapTextureName: string | null;
  environmentMapStrength: number | null;
  transMapSource: string | null;
  lightMapTextureName: string | null;
  unsupportedCommands: string[];
};

export type OmsiSceneryObjectGeometry = {
  meshes: Array<{
    declaredPath: string;
    lodThreshold: number | null;
    materialOverrides:
      OmsiSceneryMaterialOverride[];
    geometry: OmsiO3dGeometry;
  }>;
};

export type HostMessage =
  | {
      type: "omsiRootSelected";
      rootPath: string;
    }
  | {
      type: "mapOpened";
      initialTile: {
        x: number;
        y: number;
      } | null;
      map: OmsiMap;
    }
  | {
      type: "selectionCancelled";
      target: "omsi" | "map";
    }
  | {
      type: "sceneryLibraryLoaded";
      entries: SceneryLibraryEntry[];
    }
  | {
      type: "splineLibraryLoaded";
      entries: SplineLibraryEntry[];
    }
  | {
      type: "objectInserted";
      directoryName: string;
      backupDirectory: string;
      placedObject: OmsiPlacedObject;
    }
  | {
      type: "objectTransformsSaved";
      directoryName: string;
      editsSaved: number;
      filesSaved: number;
      backupDirectory: string;
    }
  | {
      type: "objectDeleted";
      directoryName: string;
      objectId: number;
